// Emoji 含义说明内容生态（P2-2）
// 键 = emoji 字符本身（build-site.js 会用 emojiHex 换算成详情页键）
// 字段：zh 中文含义 / en 英文含义 / pop 网络流行义（可省略）/ tip 使用提示（可省略）
// P2 扩写：188 条高频 emoji 注释，zh 扩至 200-300 字，覆盖使用场景、情绪强度、易混淆对比
module.exports = {
  '😀': {zh: "这是最基础、最中性的笑脸，在日常聊天里几乎百搭：朋友发来「周末一起吃饭吗」回一个它，表示欣然答应但情绪平淡；工作群里同事分享了好消息，用它回应既礼貌又不会显得过度热情；就连家人问「在干嘛」，它也能安全接住。情绪强度偏温和，属于「礼貌性开心」的起步档，比 🙂 多了张嘴笑的动感，却还没到 😄 那种眯眼大笑的兴奋。与 😄 的区别在于眼睛：😀 是圆眼睛直视，😄 是弯弯的笑眼；与 😃 的差别则在嘴——😃 张嘴幅度更大、笑声更外放，像真的笑出了声。", en: "The classic grinning yellow face with round eyes and a wide open smile. It is the most neutral and versatile happiness emoji, used as a polite default acknowledgment in both casual chats and work groups. Unlike the more excited 😄, its open eyes keep the tone grounded rather than overjoyed.", pop: "聊天中最中性的「我在笑」表达。", tip: "语气偏平淡；想要更热情可用 😄 或 😆。"},
  '😃': {zh: "这是把 😀 的嘴再张大一圈的版本，像在开心地「哈哈」出声。朋友讲了个冷笑话，或收到惊喜礼物时回它，比 😀 更有现场感和感染力；同事顺利拿下项目在群里报喜，用它捧场也恰到好处；收到心仪的面试通过通知，配它表示真心为自己高兴。情绪强度温和偏上，介于 😀 与 😄 之间——嘴张得大但眼睛仍是圆睁的，说明笑得真诚却还没笑到眯眼。与 😄 的关键区别在眼型：😃 眼睛圆、😄 眼睛弯成月牙；相比之下它少了几分笑出褶子的松弛感，多了一分大方爽朗。", en: "This face grins with an even wider open mouth than 😀, conveying audible, hearty laughter. It reads as cheerful and enthusiastic in both social and workplace conversations. Its round, open eyes distinguish it from the squinting joy of 😄, marking it as warm but not over-the-top."},
  '😄': {zh: "张嘴大笑配上眯成弯月的眼睛，是「真心实意开心」的标准配置。晒出旅行照片、收到夸奖、朋友聚会合照发群里，配上它立刻把喜悦拉满；日常被人逗乐时用它，比 😀 更显发自内心；抢到限量款、抽中奖品这种小确幸也适合。情绪强度偏强烈但仍在正常范围，是 😀 往上的第二档，已经笑到眼睛眯成缝。它和 😃 的差别就在眼睛：😄 笑到眼睛眯成缝、😃 眼睛还睁着；和 😁 的区别在于嘴——😄 是张大嘴露齿，😁 是收着的露齿笑，更内敛得意。", en: "A wide open grin paired with smiling, crescent eyes signals genuine, unreserved joy. It is commonly attached to photos of good meals, trips, or wins shared with friends. The closed, curved eyes set it apart from the still-open-eyed 😃, and its wide mouth differs from the tighter, self-satisfied grin of 😁."},
  '😁': {zh: "这是一种「偷偷得意」的笑：眼睛弯成两条线，嘴角咧出整齐一排牙，像考试考了高分或悄悄搞到限量周边时压不住的满足。汇报完工作领导点头、抢到秒杀好物、默默减肥成功被人夸瘦了，发它低调又带点小骄傲。情绪强度温和，重点不在大笑而在暗自得意，是那种「嘴上不说心里乐开了花」的表情。与 😄 的区别是嘴——😁 嘴咧得更宽、牙齿整齐外排却收着劲；与 😆 的区别是它没有皱鼻挤眼，表情更收敛，像在微笑中藏了点小心思，让人觉得你有事瞒着。", en: "This beaming face with squinting eyes and an even row of teeth conveys quiet satisfaction and smug delight. It fits moments like nailing a task or landing a hard-to-get item. Its narrower, contained grin distinguishes it from the open-mouthed joy of 😄 and the crinkled, loud laughter of 😆."},
  '😆': {zh: "皱起鼻子、眯紧眼睛、咧嘴大笑，像笑到肚子都疼了。刷到沙雕短视频、朋友爆出自黑照，连发好几个它表示真的笑崩了；群里有人讲冷笑话翻车，刷一排 😆 就是「笑到不行」；看到新闻里离谱到离谱的操作，它也是第一反应。情绪强度强烈，是笑脸家族里的高能档，比 😄 更失控，已经笑到五官挤在一起。与 😅 的区别是它没有汗滴，笑得毫无压力、纯粹开心；与 😂 的区别是没有眼泪——😆 是笑到皱脸，😂 是笑到流泪，程度再升一级。", en: "Crinkled, squeezed-shut eyes and a wide grin capture hearty, uncontrollable laughter. It is the go-to reaction to absurd memes, silly videos, or a friend embarrassing confession. Without the sweat drop of 😅 or the tears of 😂, it signals pure, pained laughter that falls between the two on the intensity scale."},
  '😅': {zh: "一边微笑一边挂着一滴冷汗，是「尴尬而不失礼貌」的万能化解符。工作群里被指出方案漏洞、约会迟到半天，回一个 😅 就是在说「不好意思我知道离谱」；朋友吐槽你又鸽了，它能缓和气氛；记错别人名字、说错话圆不回来时，它也是台阶。情绪强度温和，表面在笑实则在圆场，笑意里透着一丝心虚。与 😆 的区别就在那滴汗——😅 是笑中带尬，😆 是纯粹的笑；与 😬 的区别是嘴型，😅 还保持着微笑弧度，😬 是僵硬的龇牙，更接近紧张硬撑。", en: "A smiling face with a single bead of cold sweat is the universal emoji for an awkward but polite recovery. It softens awkward confessions, missed deadlines, or mild mistakes in chats and work groups alike. The sweat drop marks it apart from pure laughter like 😆, and its relaxed smile differs from the rigid, tense grimace of 😬.", tip: "工作群里「这个需求有点难」常用它化解尴尬。"},
  '🤣': {zh: "笑到在地上打滚的具象化：眼睛紧闭、张嘴大笑，旁边还飘着几颗笑出来的小星星。看到离谱到无语的操作、沙雕新闻大反转，连发三个 🤣 表示笑到失控；朋友分享你的社死现场，它是捧场标配；刷到动物翻车视频，刷一排它表示已笑晕。情绪强度夸张，是笑哭系里比 😂 更外放的一档，已经带上了肢体动作的戏剧感。与 😂 的区别在于没有泪珠——😂 是笑出眼泪，🤣 是直接笑到趴下；与 😆 相比它多了一层「笑到身体失控」的夸张表演成分。", en: "Depicting someone rolling on the floor with eyes squeezed shut, this emoji signals extreme, almost physical hilarity. It is often spammed three in a row against absurd memes or jaw-dropping fails. Without the tear drop of 😂, it reads as even more unhinged laughter, pushing beyond mere tearful joy into comedic collapse.", pop: "与 😂 同义，情绪更夸张。"},
  '😂': {zh: "经典的「笑哭」：眼角挂着两滴大笑出来的眼泪，嘴角咧到耳根。从家人群聊到职场沟通几乎无所不能——遇到好笑的事笑，遇到尴尬的事也拿它自嘲；「今天又加班到十点 😂」就是把无奈裹在笑声里；朋友问你怎么还单身，它也能半开玩笑地接过去。情绪强度强烈，使用场景极其宽泛，是当之无愧的万能笑脸。与 🤣 的区别是有泪珠，强调笑出泪而非笑到打滚；与 😅 的区别是它没有那滴冷汗，情绪更纯粹——不过在中文语境里两者常被混用来自嘲。", en: "The iconic teary-eyed laugh, long the most-used emoji worldwide, works for genuine humor as well as self-deprecating awkwardness. Its two teardrops distinguish it from the sweat-drop awkwardness of 😅 and the floor-rolling physical comedy of 🤣. Thanks to its flexibility, it is the default reaction across both casual and professional chats.", pop: "曾多年蝉联全球最常用 emoji。", tip: "也被用来「苦笑」化解尴尬，语境决定含义。"},
  '🙂': {zh: "淡淡的一抹微笑，嘴角只是微微上扬，眼睛平静地看着你。长辈群里回复「收到」「好的」用它最稳妥；同事发来通知，回一个 🙂 表示已读又不失距离感；领导在群里发了句鼓励，配它回应既恭敬又不谄媚。情绪强度中性，几乎不带情绪色彩，像现实中那种礼貌性的嘴角上扬。与 😀 的区别是嘴没张开、笑更收敛；与 😊 的区别是没有笑弯的眼睛——正因为太平静，它在年轻人间有时反被读出「假笑」「冷漠」的潜台词，用之前要留意对象和场合。", en: "A faint, closed-mouth smile with steady eyes is the emoji equivalent of a polite nod. It reads as neutral acknowledgment, safe for replying to elder relatives or formal announcements. Its understated, almost expressionless quality means younger users sometimes read hidden passive-aggressiveness into it, unlike the visibly warm smile of 😊."},
  '😉': {zh: "一只眼睛俏皮地眨一下，嘴角带着笑，潜台词是「懂的都懂」「咱俩心照不宣」。约朋友偷偷溜出去吃火锅、发个半开玩笑的小坏主意，眨眨眼就是「你懂我意思」；和老同事私下吐槽一句，它也能表示「这事儿别声张」。情绪强度温和，主打俏皮和暗示，比普通微笑多了一层只有你们懂的默契。与 😄 的区别是单眼眨眼带来了私下默契的含义；与 😜 的区别是它没吐舌头，暗示得更克制、更含蓄。注意职场正式沟通里少用，容易显得油滑、不够庄重。", en: "One eye playfully winking with a slight smile signals a shared secret, a playful hint, or a cheeky aside. It fits inside jokes and lightly teasing plans between friends. Since the wink adds a layer of conspiratorial flavor absent from a plain 😄, it is best avoided in strictly formal business writing where it can seem glib.", tip: "商务场合慎用，容易显得不够正式。"},
  '😊': {zh: "弯弯的笑眼配上柔和的微笑，像那种脾气很好、让人如沐春风的人。客户感谢、同事帮忙后说「辛苦啦」，配它得体又温暖；安慰情绪低落的朋友，它也比直接抱抱更轻盈；给长辈拜年时配上它，乖巧又讨喜。情绪强度温和偏暖，是「友好」表情里最安全的一个，几乎不会被误解成别的意思。与 🙂 的区别是眼睛弯成了月牙，暖意肉眼可见；与 😇 的区别是没有头顶光环，不靠「无辜」人设，纯粹的善意和亲和力。日常沟通用它几乎零风险，长辈和客户面前都安全。", en: "Warm crescent eyes paired with a gentle smile radiate approachability and kindness. It is a safe, friendly choice for thanking colleagues, comforting a friend, or softening a message. Its visibly curved eyes make it warmer than the neutral 🙂, while lacking the halo-and-innocence gimmick of 😇."},
  '😇': {zh: "头顶一圈柔和光环、闭着眼安详微笑，表面是纯洁天使。实际使用中更常被拿来「装无辜」：刚偷吃完零食被问，回 😇；悄悄办了件好事被发现，发它邀功；做了小坏事想蒙混过关，它就是你的挡箭牌。情绪强度温和，带点俏皮的反差萌——越一本正经越显得你在演戏。与 😊 的区别就在于这圈光环——把普通微笑升级成「我是乖宝宝」的人设；与 🥰 的区别是没有爱心元素，不走甜宠路线，而是走纯洁无辜的反差路线。越是一本正经，越显得你在装无辜演戏。", en: "With a soft halo above serene closed eyes, it superficially represents innocence, but online it is often used tongue-in-cheek to play the angel after a mischievous deed. The halo is the whole story: it turns a warm smile into a \"who, me?\" act, distinguishing it from the plain friendliness of 😊 and the affectionate hearts of 🥰.", pop: "常被用来「装无辜」或表示做了好事。"},
  '🥰': {zh: "微笑的脸周围飘着好几颗小爱心，像整个人都被甜意包围。收到对象发来「想你了」、吃到好吃到爆的甜品、看到萌宠视频，用它表达被萌化、被甜到的心情；朋友官宣恋情，发它表示真心祝福；孩子画了幅画送你，它也能接住那份软乎乎的感动。情绪强度温和偏甜，比 ❤️ 多了一张脸，软萌感更强、攻击性为零。与 😍 的区别是它眼睛还是普通的弯眼笑，没有变成爱心眼；与 😊 的区别在于爱心环绕这一元素，让「喜欢」从表情本身扩散到全身。", en: "A smiling face ringed with floating little hearts conveys being utterly sweetened or charmed. It suits romantic messages, adorable pet videos, or genuinely delightful little moments. The surrounding hearts make it softer than a plain red ❤️, while its normal curved eyes keep it gentler than the heart-eyed infatuation of 😍.", pop: "比 ❤️ 更软萌，适合亲密关系。"},
  '😍': {zh: "两只眼睛直接变成了红彤彤的爱心，嘴还开心地张着，几乎把「我喜欢死了」写在脸上。刷到爱豆舞台截图、朋友晒新包包、看到菜单上想吃的菜，立刻甩出它表示心动；看到多年偶像官宣、心仪已久的商品打折，它也是必发反应。情绪强度强烈，是颜值与物品崇拜的标配，喜欢的情绪直接糊在脸上。与 🥰 的区别在于眼睛本身就是爱心，冲击力更直接；与 🤩 的区别是 🤩 是星星眼，表达的是惊艳崇拜，而 😍 强调的是喜欢和爱慕。几乎是追星和夸颜值时的第一反应，饭圈标配。", en: "With both eyes literally turned into red hearts and an open grin, it broadcasts immediate adoration or infatuation. It is attached to photos of a celebrity, a desirable product, or mouth-watering food. The heart-shaped eyes distinguish it sharply from the soft floating hearts of 🥰, and from the star-eyed awe of 🤩.", pop: "追星、夸颜值、看到好东西时用。"},
  '🤩': {zh: "眼睛闪着星星、嘴张得大大的，像第一次见到烟花的小孩，满是惊艳和崇拜。看到偶像线下舞台、得知心仪公司发来 offer、朋友秀出超酷的爱好，用它表达「我震惊了我佩服」；听到一个绝妙的创意方案、看到神级操作，它也能立刻接上。情绪强度强烈，偏兴奋和大开眼界。与 😍 的区别是星星眼代表惊艳、佩服、大开眼界，不一定是喜欢某个人，更偏向被震撼；与 ✨ 单独使用相比，这张脸把眼前一亮具象成了人物表情，更生动。比打一串惊叹号更传神，画面感十足。", en: "Star-shaped eyes and a wide open mouth capture wide-eyed awe and enthusiastic admiration. It reacts to a stunning performance, an exciting opportunity, or someone impressive achievement. Its star eyes signal being dazzled or impressed rather than the romantic infatuation carried by the heart eyes of 😍."},
  '😘': {zh: "嘟起嘴唇、飞出一颗小红心的飞吻，像恋人间或妈妈对孩子的那个亲亲。对象睡前道晚安、闺蜜帮了大忙、孩子亲完屏幕，发它表达爱意和撒娇式感谢；异地恋分别时，它也能隔着屏幕补一个亲亲。情绪强度温和偏亲昵，带有明显的亲密关系信号，不是谁都能发。与 😗 的区别是多了飞出的爱心和眨眼动作，感情浓度更高、更外放；普通同事间慎用，容易引起误会，家人和亲密朋友之间则很自然。发错对象会很尴尬，关系不到别轻易用，分寸感很重要。", en: "A pursed-lip blow kiss with a little floating heart conveys affection, thanks, or affectionate teasing. It is typical between partners, close friends, or family members. The added heart and wink make it more emotionally loaded than the plain peck of 😗, so it can feel out of place with casual colleagues.", tip: "亲密对象/家人之间使用，普通关系慎用。"},
  '😗': {zh: "一张没有情绪起伏、微微嘟起嘴唇的脸，安安静静送一个吻。比 😘 含蓄，像轻轻碰一下脸颊那种礼貌式的亲亲。长辈表达疼爱、老朋友之间说「爱你哟」、妈妈发来「照顾好自己」，用它就够，点到为止。情绪强度温和内敛，不撒娇、不热烈，更像一个礼节性的吻面礼。与 😘 的区别是没有飞出的爱心、也没有眨眼，更像一个静态的亲吻动作；与带红晕的飞吻相比，它连脸红都没有，完全走朴素路线。适合长辈和老朋友之间，点到为止不越界。", en: "A plain, calm face with pursed lips gives a quieter, more restrained kiss than the blow-kiss emoji. It suits gentle affection from elders or understated warmth between longtime friends. Without the flying heart and wink of 😘, it keeps the gesture minimal and decorous."},
  '😋': {zh: "眯着眼睛、得意地伸出舌头舔一下嘴唇，像刚吃到人间美味。晒火锅、晒奶茶、晒妈妈做的菜，文案后面必跟一个；自己嘴馋跟朋友约饭，它也是「好想吃」的招牌；深夜放毒发美食图，配它效果翻倍。情绪强度温和，主打享受和馋，是吃货的专属表情。与 😛 的区别是 😛 是调皮地吐舌，😋 的舌头是舔嘴唇、明显围绕美食满足；与 🤤 的区别是 🤤 嘴角流口水，更接近垂涎三尺，而 😋 是已经吃到了的满足感。堪称吃货圈的通行证，晒图必配。", en: "Squinted eyes and a tongue licking the lips signal savoring delicious food or craving a tasty meal. It is the natural caption companion for hotpot photos, desserts, or teasing plans to eat out. The lip-licking action is food-focused, unlike the purely playful tongue of 😛 or the drooling craving of 🤤.", pop: "发美食图标配。"},
  '😛': {zh: "眼睛直直看着你、俏皮地吐出一小截舌头，像做了鬼脸说「略略略」。和朋友互怼开玩笑、故意说句气人的小话后甩它，就是在声明「我在逗你玩别当真」；逗小孩、跟宠物卖萌时它也派得上用场。情绪强度温和，带点调皮捣蛋，是朋友之间互相拆台的润滑剂。与 😋 的区别是它舌头只是调皮地伸出来，和美食无关；与 😜 的区别是它没有眨眼，搞怪得更直白；与 🤪 的区别是后者整个脸都歪了，疯癫程度更高。它点到为止，适合朋友间互相拆台。", en: "A straight-faced stare with a small stuck-out tongue is a classic raspberry-style tease. It defuses a playful jab or lighthearted provocation among friends. Unlike the food-associated tongue of 😋, it is purely mischievous; and without the wink of 😜 or the whole-face wobble of 🤪, its goofiness stays straightforward."},
  '😜': {zh: "一只眼眨着、另一只眼斜着，舌头调皮地伸出来，像对着镜头做鬼脸搞怪。群里发自己的囧照、开玩笑说「我才没有偷懒 😜」、故意出个馊主意，它把玩笑和默契叠在一起；朋友间互相揭短时甩它，表示我说归说、别往心里去。情绪强度温和偏闹，介于正经玩笑和发疯之间。与 😛 的区别是多了眨眼，「我在跟你开玩笑」的信号更明确；与 😉 的区别是多了吐舌头，比单纯眨眼更夸张、更不正经，适合关系好的朋友之间互侃。不熟的人慎用，容易显得没分寸。", en: "A winking, sideways glance with a stuck-out tongue is a cartoonishly playful prank face. It accompanies teasing jokes, self-deprecating silly photos, or obviously bad ideas you want labeled as a joke. The wink makes its \"I am kidding\" signal stronger than a plain 😛, while the tongue goes further than the subtle hint of 😉."},
  '🤪': {zh: "两只眼睛一上一下、整个脸歪歪扭扭、舌头歪歪吐出，像喝嗨了或者彻底放飞自我。团建玩嗨、朋友聚会喝到微醺、自嘲「今天脑子不太好使」，用它表示整个人都有点不正常；加班到头昏脑胀、连续开会三天后，它也能形容那种精神恍惚。情绪强度夸张，是鬼脸家族里最疯的一档，已经不讲究表情管理。与 😜 的区别是 😜 只是局部吐舌眨眼，🤪 整张脸都歪了，疯癫感拉满；与 🥴 的区别是它强调搞怪欢乐，🥴 强调头晕醉酒的生理感。主打放飞自我，正经场合别用。", en: "With crossed-off-kilter eyes, a lopsided face, and a crooked tongue, it embodies goofy, off-the-wagon fun. It suits late-night group banter, slightly tipsy party moments, or self-deprecating jokes about being scattered. Its whole-face wobble makes it wilder than the limited tongue-wink of 😜, and more celebratory than the dizzy, queasy feel of 🥴."},
  '🤗': {zh: "圆圆的脸咧着嘴笑，两只小手张开放在身体两侧，像在说「来抱一个」。朋友面试通过、家人遇到喜事，发它送上拥抱式鼓励；安慰受挫的同事，它比一串文字更有温度；看到久别重逢的消息，它也是隔空一个拥抱。情绪强度温和，主打温暖和支持，是表达善意最不具攻击性的方式之一。与 🥰 的区别是它的核心动作是张开双臂拥抱，不强调爱情，家人朋友都能用；与 👏 的区别是它是一张脸带手臂的表情，情绪属性更强、鼓掌属性更弱。是个温暖的表情，安慰人时很合适。", en: "A grinning face with two open arms reaching out offers a virtual hug of welcome, comfort, or support. It celebrates a friend win, consoles someone set back, or just says \"you have got this.\" The outstretched arms are the key: it is about embrace and encouragement, unlike the floating hearts of 🥰."},
  '🤭': {zh: "一只手捂住嘴，眼睛瞪得圆圆的，像突然想笑又憋住、或者刚听到了不能外传的小八卦。同事在群里吐槽老板被你撞见、朋友说出糗事，回它表示「我懂我懂忍住了」；听到一个惊天大瓜，它就是你捂嘴震惊的样子；别人讲了个荤段子，它也能表示「嘘小点声」。情绪强度温和，带点窃喜和惊讶。与 🤫 的区别很关键：🤫 把食指竖在嘴前要求保密，🤭 是捂嘴本身——一个是「别说了」，一个是「我憋不住笑了」；与 😮 的区别在于捂住嘴这个动作本身就带笑意。", en: "A hand pressed over a wide-eyed mouth captures stifled laughter, a gasp, or newly overheard gossip. It reacts to a juicy secret, a friend awkward admission, or something you find hilarious but must keep a straight face. The hand-over-mouth pose shows suppressed amusement, whereas the finger-to-lips of 🤫 is purely a demand for silence."},
  '🤫': {zh: "食指竖在嘴唇前，眼睛半睁，像在说「嘘——小声点」。拜托朋友帮忙保密、群里别再 @ 当事人、深夜怕吵到家人想收尾聊天，用它示意安静；想让同事别在大群里讨论敏感话题，发它最传神；答应别人「这事儿我绝不外传」时，它也是盖章认证。情绪强度中性偏严肃，不是玩笑而是明确的指令。与 🤭 的区别很关键：🤫 是主动要求安静或守口如瓶，🤭 是捂嘴忍笑，一个命令一个自嗨。职场里「这条消息别外传」配它非常合适。比打字说「嘘」更传神，一眼就懂。", en: "An index finger held to the lips is a clear \"shh\" for quiet, discretion, or keeping a secret. It asks someone to stay discreet, stop pinging a sensitive topic, or wind down a late-night chat. The finger-to-lips gesture is a direct request, distinguishing it from the self-conscious suppressed laughter of 🤭."},
  '🤔': {zh: "一只手托着下巴，眼睛斜斜看向一边，像在认真琢磨事情。工作群里收到需求，先回个 🤔 表示「让我想想怎么弄」；朋友抛出一个奇怪的问题，它也表示我正在评估这靠不靠谱；面对「中午吃什么」这种世纪难题，它更是标配。情绪强度中性，是思考和犹豫的万能符号，既不拒绝也不答应。与 🤨 的区别是 🤨 挑单眉带怀疑，🤔 更中性、偏思考；与 😐 的区别是它明显有「在琢磨」的动作，不是彻底无语，而是还在权衡。不会轻易给答案，先拖一拖。", en: "A hand on the chin with a sideways gaze embodies pondering, weighing options, or genuine hesitation. In work chats it softly says \"let me think about it\"; among friends it signals \"I am evaluating this claim.\" The thinking pose is neutral and deliberative, unlike the accusatory skepticism of 🤨 or the flat emptiness of 😐.", tip: "职场「让我想想」的常用表情。"},
  '🤨': {zh: "一边眉毛明显挑起，眼神斜斜瞟过来，写满了「真的假的？你认真的？」。朋友又说自己能熬夜三天、同事提出离谱方案、家人说「我这菜特别健康」，回一个挑眉就是在质疑；听到一个数字离谱的报价，它也能秒接。情绪强度偏强烈，带刺但还没翻脸，属于「我先看看你在说什么」。与 🤔 的区别是 🤔 托腮思考，🤨 是直接挑眉质疑，怀疑已经写在脸上；与 😏 的区别是 😏 是得意坏笑，🤨 是不以为然，情绪方向完全相反。一个质疑一个得意，用错了会闹误会。", en: "One raised eyebrow and a sidelong glance broadcast skepticism and \"seriously?\" disbelief. It reacts to a far-fetched claim, an offhand excuse, or a plainly suspect idea. The arched brow is a direct challenge, unlike the open pondering of 🤔; and it reads as disbelief, the opposite of the smug confidence of 😏."},
  '😐': {zh: "一张几乎毫无起伏的脸：眼睛两条直线，嘴巴一条横线，像被生活磨平了棱角。听到又一个临时需求、群里陷入无聊争论，发它表示「我没什么好说的」；领导在群里画了个大饼，它也能表示听着但不表态；朋友絮叨半天，它就是「哦」的升级版。情绪强度中性，表面平静其实常常藏着无语和麻了。与 😑 的区别是 😐 还保留一点中性的「我在听」，😑 连眼睛都闭起来了更冷淡；与 😶 的区别是 😶 直接没有嘴，连表情都懒得给。主打一个心如止水，听着但不表态。", en: "A perfectly flat, straight-line face — level eyes, horizontal mouth — is the visual equivalent of \"I have no comment.\" It registers weary resignation to yet another last-minute task, or silence in a tedious debate. It is less closed-off than the fully deadpan 😑 (whose eyes are shut) and less emptied-out than the mouthless 😶.", tip: "也常被用来表达「我麻了」。"},
  '😑': {zh: "眼睛闭成两条直线、嘴也是一条平线，整张脸像在说「我已放弃表情管理」。听到重复第三遍的废话、被反复要求改方案、客户改了八版又要第一版，它表达那种连翻白眼都懒得的冷淡和无奈；同事又甩锅过来，它也能表示我懒得争了。情绪强度偏冷淡，比 😐 更进一层，是「闭眼拒绝」的状态。与 😐 的区别就在闭着的眼睛——😐 还睁着眼听，😑 已经闭上眼不想看；与 😶 的区别是它有嘴但什么都不说，😶 连嘴都没有。已经放弃交流，懒得再争论。", en: "Closed, level eyes and a flat straight mouth convey deeper deadpan resignation than the already neutral 😐. It reacts to repetitive lectures, frustrating loops, or being too tired to even roll eyes. Its shut eyes mark a step colder than 😐, while it still keeps a mouth — unlike the mouthless blankness of 😶."},
  '😶': {zh: "一张有眼睛却没有嘴巴的脸，像话到嘴边突然说不出来。听到离谱到震惊的消息、被怼得无言以对、社死之后只想沉默，发它就是「我失语了」；别人发了一个不知道怎么接的话，它也是最安全的回应；群里有人开始抬杠，发它表示我不参与。情绪强度中性偏沉默，主打「无话可说」。与 😑 的区别是它用「没有嘴」这个设计本身表达失语，而 😑 有嘴但懒得动；与 😮 的区别是 😮 是张嘴的惊讶，😶 是连嘴都没有的沉默。适合接不住的话，沉默是金。", en: "A face with eyes but no mouth is designed around speechlessness — words failing you, stunned silence, or being left without a comeback. It reacts to jaw-dropping news or the moment you realize you have said something embarrassing. The missing mouth is the whole statement, distinguishing it from the mouth-but-silent 😑 and the open gasp of 😮."},
  '😏': {zh: "嘴角单边向上翘起、眼神斜睨，一脸「我就知道」「这事儿稳了」的得意。考试估分很有把握、棋走一步就料到对方要输、悄悄完成了别人没发现的事，发它低调炫耀；跟朋友打赌赢了、提前知道了一个小内幕，它也是藏不住的小嘚瑟。情绪强度偏强烈，带点小坏和自信。与 😎 的区别是 😎 戴墨镜走冷酷路线，😏 是没戴眼镜的得意坏笑，更接近「阴谋得逞」；与 🤨 的区别是后者在质疑，😏 在自满，情绪方向相反。藏着小得意，别被人看出来。", en: "A one-sided smirk with a sidelong look says \"I knew it\" or \"this is already handled.\" It quietly celebrates a win you predicted, a clever move, or a secret well-played trick. The asymmetric smirk conveys smug confidence, unlike the cool sunglass composure of 😎 or the skeptical brow of 🤨."},
  '😒': {zh: "嘴角向下一撇、眼睛斜着翻上去，一脸嫌弃和不悦。听到同事又甩锅、朋友讲了让人下头的话、家人又开始催婚，回它表达「行吧，我不评价」；看到有人公然双标，它也是无声的抗议。情绪强度偏强烈，带不满但还没爆发，属于「我不跟你一般见识」的冷脸。与 🙄 的区别是 🙄 是明显的翻白眼，😒 是撇嘴式的不悦，收敛一点；与 😏 的区别是一个嫌弃一个得意，嘴角方向正好相反，用错了会闹误会，一个是嫌弃一个是得意，千万别用反了。", en: "A downturned mouth and a sideways, annoyed look express displeasure, dismissal, or muted disapproval. It reacts to excuses, cringey remarks, or the urge to just drop a conversation. Its pouted dissatisfaction is subtler than the overt eye-rolling of 🙄, and the opposite of the smirking satisfaction of 😏."},
  '🙄': {zh: "两个眼珠直接翻到头顶、嘴角还撇着，把「我服了」「不想说了」写在脸上。群里有人胡搅蛮缠、朋友又吹牛皮、对象又忘事，发它就是懒得理；看到朋友圈有人凡尔赛，它也是标配反应。情绪强度强烈，带不耐烦和无语，已经到了「我拒绝交流」的边缘。职场里用它容易显得态度冲，熟人互侃则很自然。与 😒 的区别是 🙄 把眼睛整个翻上去更夸张；与 😑 的区别是 😑 已经闭眼放弃，🙄 是还睁着眼翻白眼，情绪还没压下去。已经很不耐烦了，熟人局才好用。", en: "Eyes rolled fully upward with a downturned mouth are the picture of \"I am done.\" It signals exasperation at nonsense, bragging, or an unreasonable argument. Because it reads as visibly impatient, it is better among close friends than in formal settings; the full upward roll is more extreme than the side-eye pout of 😒.", tip: "语气偏冲，职场慎用。"},
  '😬': {zh: "整排牙齿僵硬地露出来、眉毛皱成八字，像被逼到墙角硬着头皮笑。答应完突然发现做不到、deadline 比想象紧、被当众点名，发它表示「我人在这但很尴尬」；临时被拉去开会、在群里被 @ 回答答不上来，它就是你的救场表情。情绪强度偏强烈，主打紧张尴尬，是「强颜欢笑」的具象。与 😅 的区别是 😅 是挂着汗的礼貌笑，😬 是咬牙式的僵硬，更接近内心崩溃；与捂眼偷看的区别在于它是直面尴尬、无处可躲。救场必备，尴尬时甩它准没错。", en: "A rigid grin showing clenched teeth with furrowed brows is the \"I am in trouble but I will smile through it\" face. It reacts to an impossible commitment, a scary deadline, or being put on the spot. Its strained, clenched quality differs from the polite sweat-drop smile of 😅; it is about visible awkwardness, not covert nervousness.", pop: "在群里回复「这个 deadline 有点紧」常配它。"},
  '🤥': {zh: "鼻子像匹诺曹一样拉长一截，眼睛却还无辜地笑着，把「撒谎」「吹牛」直接打在公屏上。朋友又说「我这次真的只喝一口」、同事甩锅被你当场看穿、家人自夸从没迷路，发它就是在戳穿对方；看到朋友圈夸大其词的文案，它也是拆穿标配。情绪强度中性偏调侃，不真的生气，更多是「我看你演」的戏谑。与 😏 的区别是 😏 是自己暗自得意，🤥 是直接指认别人在说谎；与 🤔 的区别是 🤔 还在怀疑阶段，🤥 已经判定对方在吹牛了。一戳一个准，朋友间拆台专用。", en: "A Pinocchio-style elongated nose on an otherwise smiling face openly calls out lying or exaggeration. It reacts to obvious excuses, boastful self-puffery, or transparently bad cover stories. The lengthened nose turns it into a cartoon lie detector — a direct accusation, not the quiet suspicion of 🤔 or the smugness of 😏."},
  '😔': {zh: "眉头微微下垂、眼神看向斜下方、嘴角轻轻沉下去，像一件事没办好后独自惆怅。精心安排的周末突然泡汤、错过了喜欢的展览、考试就差几分及格，发它表达心里那点闷闷不乐；养的小植物枯了、朋友好久没联系，它也能接住那种淡淡的失落。情绪强度温和，是低气压的起点，还没到痛哭，更多是叹气式的遗憾。与 😞 的区别是它更内敛、只是低头叹气式的惆怅；与 😢 的区别是它没有泪珠，情绪还压在心里没有外放。淡淡的失落感，比大哭更含蓄。", en: "Drooping brows, downward gaze, and a slight downturned mouth convey quiet disappointment and wistfulness. It reacts to a cancelled plan, a missed opportunity, or narrowly missing a goal. Its muted inward sadness keeps it gentle, unlike the tearful grief of 😢; it is melancholy rather than outright misery."},
  '😪': {zh: "一只眼皮耷拉着、半闭着眼，旁边挂着一滴困倦的泪，像熬夜到凌晨那种睁不开眼。加班到很晚、早八的课、周日下午困到睁不开，发它表示「我快不行了」；连续开了一下午会、长途车坐到犯困，它也是「电量不足」的信号。情绪强度中性，主打生理疲惫，困意大于情绪。与 😴 的区别是 😴 已经闭眼睡死、还打 Zzz，😪 是还在硬撑的半梦半醒；与打哈欠的区别在于它更偏「困到流泪」，比单纯打哈欠更没精神。困到灵魂出窍，还在硬撑。", en: "Half-closed drooping eyes with a single tired tear capture heavy, eyelids-crashing exhaustion. It reacts to late-night overtime, an early morning class, or a Sunday afternoon slump. It is the \"still holding on\" state — more awake than the fully conked-out, ZZZ-dreaming 😴, and more teary-drowsy than a simple yawn."},
  '🤤': {zh: "嘴角淌着一缕口水、眼睛半闭一脸陶醉，像看到好吃的、好看到要流口水。刷到深夜放毒的美食视频、朋友晒出限量球鞋、看到心仪对象，发它表示馋到不行；看到心仪已久的车型、朋友秀出刚买的宝贝，它也是「我也好想要」。情绪强度偏强烈，带点花痴和垂涎，欲望写在脸上。与 😋 的区别是 😋 是舔嘴满足，🤤 是直接流口水，更直白；与 😍 的区别是 😍 是爱心眼喜欢，🤤 偏垂涎三尺的欲望感，更外露。馋到毫不掩饰，看到好东西就流口水。", en: "A drooling, half-lidded blissed-out face says \"I want that badly.\" It reacts to late-night food videos, coveted sneakers, or someone you find attractive. The literal drool makes the craving more overt than the contented lip-lick of 😋; it leans toward hungry desire rather than the romantic infatuation of 😍."},
  '😴': {zh: "双眼紧闭、表情安详，鼻子旁飘着一串大大的「Zzz」，像已经睡得很沉很香。深夜群聊想收场、跟家人说「我先睡了」、假装这话题无聊到自己睡着，发它最省事；下午开会困得睁不开眼，它也是「我灵魂已经出窍」的自黑。情绪强度中性，主打睡眠状态本身，是结束对话的礼貌信号。与 😪 的区别是 😪 还在挣扎着不肯闭眼，😴 已经彻底入睡、连鼾都打起来了；与打哈欠的区别是它直接进入梦乡而非打哈欠。晚安信号首选，结束聊天最省事。", en: "Closed peaceful eyes next to a big \"Zzz\" captures being fast asleep. It is the polite way to sign off a late-night group chat, tell family you are heading to bed, or jokingly feign boredom. It represents fully conked-out sleep, a step beyond the still-fighting sleepiness of 😪.", tip: "深夜群里发这个表示「我先睡了」。"},
  '😷': {zh: "脸上规规矩矩戴着一只蓝色医用口罩、表情平静，像感冒了乖乖戴口罩出门。流感季节戴口罩上班、自己咳嗽怕传染同事、或者用它表示「今天不想说话」，都很合适；疫情期间它更是必备，现在也延伸出「我不想接话」「别问我」的隐身用法。情绪强度中性，主打防护和沉默。与 🤒 的区别是 🤒 额头贴着体温计、明显在发烧，😷 只表示戴着口罩这一动作；疫情之后它还延伸出「我不想开口」的社交含义。也是社交隐身符，不想说话就戴它。", en: "A flat blue surgical mask over a calm face signals being sick, cautious, or wanting to stay quiet. It fits flu-season work trips, post-illness recovery, or jokingly going offline from chatter. The mask alone is the key: it does not show fever like the thermometer-adorned 🤒, and post-pandemic it is also used as \"I am not talking today.\""},
  '🤒': {zh: "额头上贴着一支体温计、眉头皱起一脸难受，明晃晃写着「我发烧了」。换季感冒请假、熬夜到身体报警、被办公室传染，发它表示自己病恹恹需要休息；跟领导请假时配它，比干巴巴说「我病了」更有说服力。情绪强度温和偏难受，主打生病状态。与 😷 的区别是 😷 只是戴着口罩防护、未必发烧，🤒 用体温计直接证明体温异常；与 🤕 的区别是 🤕 头缠绷带偏向磕碰外伤，🤒 是身体内部发烧感冒。请假必备，比干说生病更有说服力。", en: "A thermometer stuck to the forehead with a furrowed brow visibly signals fever and being under the weather. It is used to call in sick, complain about seasonal flu, or say you need rest after pulling an all-nighter. The thermometer explicitly shows illness, distinguishing it from the merely masked 😷 and the bandaged head injury of 🤕."},
  '🤕': {zh: "头上缠着一圈白色绷带、额角还贴着一块创可贴，一脸受伤的委屈。磕到桌角、周末打球摔了一跤、被连续加班折腾得「头都大了」，发它表示受伤或身心俱疲；朋友之间开玩笑说「你把我弄伤了」，它也能卖萌式卖惨。情绪强度温和，常带自嘲式的夸张，未必真伤得多重。与 🤒 的区别是它走外伤路线、有包扎元素，🤒 是发烧感冒；与 😵 的区别是 😵 只是头晕眼花没有伤口，🤕 明确受了伤需要养几天。卖惨也可爱，朋友间调侃常用，无伤大雅。", en: "A white bandage wrapped around the head with a small bandage on the forehead conveys being banged up or injured. It is literal for a bump or sports mishap, and figurative for being mentally beat after heavy overtime. The bandage marks an external wound, unlike the internal fever of 🤒 or the unbandaged dizziness of 😵."},
  '🤢': {zh: "整张脸泛出青绿色、嘴角挂着恶心的黏液，像闻到怪味或看到反胃画面时的生理反应。吃到黑暗料理、刷到重口味视频、看到离谱操作让人作呕，发它表示「我整个人都不好了」；朋友描述他多恶心的经历，它也是「听得我想吐」的回应。情绪强度强烈，主打反胃不适，已经接近生理反应。与 🤮 的区别是 🤮 已经直接吐出来，🤢 是想吐还没吐、忍在喉咙口；与 🤧 的区别是后者打喷嚏，完全是另一种生理反应。反胃感拉满，看到重口内容秒发。", en: "A greenish queasy face with drool at the corner shows physical nausea — the \"this is disgusting\" reaction. It reacts to bad food, gross content, or someone repulsive behavior. It is the holding-it-back stage: stronger than a mere 😒 but one step short of the full vomiting of 🤮."},
  '🤮': {zh: "脸憋得涨红、嘴巴张得老大、正往外大吐特吐，像恶心到彻底扛不住了。刷到生理不适的画面、被朋友的迷惑操作震惊、聚会喝多了现场直播，发它表示嫌弃值拉满；吐槽一首难听到爆的歌、一份难吃的外卖，它也能夸张地表达「我不行了」。情绪强度强烈，是恶心表情家族里的最高档，比 🤢 更不留余地。与 🤢 的区别是 🤢 只是反胃还忍着，🤮 已经真的吐出来了；它的夸张用法让它不局限于真的呕吐。吐槽利器，难听难看到想吐都靠它。", en: "A red, contorted face mid-vomit is the strongest gross-out emoji available. It reacts to physically repulsive content, jaw-droppingly bad taste, or exaggeratedly terrible things like \"this song made me throw up.\" It is the end of the nausea spectrum — one full step beyond the queasy, still-holding-it-in 🤢."},
  '🤧': {zh: "皱着鼻子、皱着眉、拿手帕捂住脸打了个大喷嚏，像感冒流鼻涕或春天花粉过敏。换季鼻子不通气、春天花粉季犯鼻炎、办公室同事感冒被传染，发它表示自己正病恹恹；擤完鼻涕跟人说话，它也是「我这边战况激烈」的自黑。情绪强度中性偏难受，主打呼吸道症状。与 🤒 的区别是 🤒 额头体温计发烧，🤧 重点在打喷嚏流鼻涕；与 😷 的区别是它拿手帕捂鼻子、没戴口罩，更偏打喷嚏本身。鼻炎季常客，春天一到就高频出现，随身带纸别问为什么。", en: "A handkerchief pressed to a scrunched-up nose mid-sneeze signals a cold, runny nose, or seasonal allergy. It is used during pollen season, a flu-spreading office, or when you are sniffling through a message. The sneezing focus distinguishes it from the fever-focused 🤒 and the masked-but-symptomatic 😷."},
  '🥵': {zh: "整张脸红得像煮熟、挂着汗珠、舌头伸出来直喘气，像三伏天走在没有树荫的马路上。没空调的房间、面试前紧张到脸红心跳、吃到变态辣火锅冒汗，发它表示燥热难耐；听到好消息激动到面红耳赤、被人夸到不好意思，它也能形容那种发烫的感觉。情绪强度强烈，表面是热，也常用来形容紧张、激动或被辣到。与 🥶 的区别是一个热一个冷；与 😅 的区别是 😅 那滴汗是尴尬的冷汗，🥵 是热到冒出来的汗。燥热感直白，热辣紧张都能套，情绪写满脸。", en: "A flushed, sweat-beaded face panting with tongue out shows being overheated — literal summer heat, spicy food, or nervous fluster. The red face and sweat convey intensity. The sweat here is heat sweat, unlike the awkward cold sweat of 😅, and it pairs as the hot counterpart to the freezing 🥶."},
  '🥶': {zh: "整张脸冻得发青、嘴唇发紫、牙齿打着颤、身边还飘着小雪花，像大冬天出门忘了穿羽绒服。零下十几度的室外、北方暖气房外的走廊、吐槽对象「对我好冷淡」，发它表示冻到僵硬；空调开太低坐久了，它也是「我快成冰棍了」。情绪强度强烈，字面是冷，网络上常引申为人的「高冷」「被冷落」。与 🥵 正好是一对冷热镜像；与 🥴 的区别是它强调冻僵的生理反应，而不是醉酒头晕。冷热一对镜像，高冷梗也靠它，反差感十足，一热一冷成对用。", en: "A blue-purple, shivering face surrounded by snowflakes shows being freezing cold. It is used for winter outings, unheated rooms, or jokingly saying someone is giving you the cold shoulder. It forms a natural hot/cold pair with 🥵, and online it is also used figuratively to call someone aloof or standoffish.", pop: "口语里常形容人很酷、很冷。"},
  '🥴': {zh: "一只眼勉强睁着、另一只眼半耷拉着、嘴角还歪到一边，像刚喝了两杯之后那种晕乎乎的状态。聚会微醺、连续加班脑子彻底转不动、听完对方一堆车轱辘话整个人都懵了，发它表示我现在有点不清醒；看完一部烧脑电影、被一堆信息砸晕，它也能形容那种天旋地转。情绪强度中性偏飘，主打微醺和恍惚。与 😵 的区别是 😵 直接 X 形眼、彻底晕眩断片，🥴 是还撑着半睁眼的微醺；与 🤪 的区别是 🤪 是搞怪发疯，🥴 重点在头晕站不稳。", en: "One eye half-open, the other drooping, with a lopsided mouth shows a woozy, tipsy, or brain-fried state. It reacts to tipsy gatherings, total exhaustion, or being talked into a daze. It is the mildly sloshed version — less blackout than the X-eyed dizziness of 😵, and more unsteady than the goofy wildness of 🤪."},
  '😵': {zh: "用于信息过载、脑子瞬间转不动的场景。比如群里突然涌进来二十条未读需求、打开一份满屏参数的技术文档、或者一分钟内被甩了三个链接时发它，表示\"我已经看懵了\"；打游戏被对手一套连招秀到原地发呆，刷到一半没看懂的长文也会发这颗 X 眼。情绪强度温和偏中性，是\"卡住但还没崩溃\"，比 🤯 的爆炸式震惊低一档，也比 💀 的\"笑死\"自嘲更偏生理性眩晕。易混淆对比：和 🥴 的区别在于，🥴 是喝醉后的松弛晕乎、嘴角歪斜带点微醺的可爱，😵 则是直接宕机的硬掉线；和 🤯 比，🤯 是爆炸式震惊，😵 是呆滞式卡死。", en: "A yellow face with X-shaped eyes and a wavy mouth, used when someone feels dazed, overwhelmed, or mentally knocked out. It often appears after a flood of messages, a wall of technical specs, or getting disoriented mid-gameplay. Unlike 🤯's explosive shock, 😵 conveys a gentler \"my brain just froze\" overload rather than true panic."},
  '🤯': {zh: "用于\"这都能行？\"式的震惊场景。比如看到离谱操作、神级剧情反转、价格低到不合常理的 deal，或者读到一个完全颠覆认知的冷知识时发它；同事随口说出一个你三年都没想通的答案，也会瞬间炸出这个表情。情绪强度强烈，是这批负面情绪表情里冲击感最高的一档，比 😵 的呆滞更外放、更夸张，属于\"认知被刷新\"而非\"情绪被吓到\"。易混淆对比：和 😱 的区别——😱 是恐惧式尖叫，重心在\"害怕\"，🤯 是认知被炸开，重心在\"世界观刷新\"；和 😵 比，😵 是卡住不动，🤯 是彻底过载到原地爆炸。", en: "A head with an exploding top and steam bursting out, expressing that one's mind has been blown by something unbelievable. It is the go-to reaction for absurd hacks, plot twists, or a bargain that seems too good to be true. Stronger and more theatrical than 😵, it focuses on cognitive shock (\"my world view just shattered\") rather than the fear conveyed by 😱.", pop: "\"这都能行？\"的标配表情，常用于对离谱操作或神级反转表示惊叹。"},
  '🤠': {zh: "用于随性、豁出去、\"说走就走\"的轻松场景。比如临时决定周末去露营、一口答应朋友一场说走就走的旅行、或者自嘲\"摆烂但很快乐\"的心态时发它；被老板突然通知周五不用汇报，也会冒出个牛仔帽表示放飞。情绪强度偏中性偏轻松，是这批\"人设类\"表情里最松弛的一个，不具攻击性，只是一种嬉皮笑脸的生活态度。易混淆对比：和 😎 的区别——😎 是墨镜式的克制酷感，重心在\"我很从容\"，🤠 是牛仔式的外放狂野，重心在\"爱谁谁\"；和 🥳 比，🥳 是庆祝特定事件，🤠 是一种随时在线的扮相。", en: "A smiling face wearing a brown cowboy hat, evoking a carefree, wild-west, nothing-to-lose attitude. It fits spontaneous plans, weekend road trips, or self-mocking \"I'm just rolling with it\" moods. Lighter and more playful than the cool composure of 😎, it reads as boisterous freedom rather than polished confidence."},
  '🥳': {zh: "用于庆祝、生日、升职、项目上线等\"嗨起来\"的场景。比如朋友考上目标学校、自己终于跑完马拉松、团队成功发布、或者抢票抢到了梦寐以求的演唱会时发它助兴；节日零点倒数也常刷它。情绪强度偏热烈，是正向情绪里较外放的一档，比 😄 的内敛开心更具派对感，是\"本人在场跟着嗨\"的现场感。易混淆对比：和 🎉 的区别——🎉 是道具式庆祝符号，🥳 是人脸表情，更强调\"当事人本人很嗨\"；和 🤩 比，🤩 是对某件事的惊艳崇拜，🥳 是对喜事本身的庆祝狂欢，对象不同。", en: "A face wearing a party hat and blowing a party horn, with confetti, used to mark celebrations, birthdays, promotions, or releases. It conveys genuine festive excitement and \"I'm right here partying.\" More participatory than the prop-style 🎉 and more about the event itself than the admiration conveyed by 🤩."},
  '😎': {zh: "用于\"我很酷、稳了、不慌\"的场景。比如顺利搞定一个别人觉得难的问题、轻松完成了高难度任务、或者想给一句平淡的话加上\"一切尽在掌握\"的滤镜时发它；晒车晒表、装帅摆拍也爱配它。情绪强度中性偏从容，是克制型的酷，不会显得张扬，比 🤠 的外放更收敛。易混淆对比：和 🤠 的区别——😎 是墨镜遮脸的内敛酷，🤠 是牛仔帽的外放野，一个闷骚一个明骚；和 😏 比，😏 的坏笑带一点得意或算计，😎 则是坦荡的从容自信，没有那层狡黠。", en: "A smiling face wearing dark sunglasses, signaling coolness, composure, and \"I've got this.\" It fits nailing a hard task with ease or playfully laying on a confidence filter. Calmer than the loud cowboy energy of 🤠 and less smug than 😏, it reads as effortless assurance rather than cunning satisfaction."},
  '🤓': {zh: "用于自嘲学霸、技术宅、书呆子气的场景。比如分享自己又熬夜研究了一个冷门知识点、写了一堆没人看的笔记、或者朋友调侃\"你这个 nerd\"时回它；晒出刚啃完的大部头、列了一长串书单也爱配这张厚框脸。情绪强度中性偏自嘲，没有真正的贬义，更多是亲昵的自我调侃，甚至带点小骄傲。易混淆对比：和 🧐 的区别——🧐 是单片眼镜的考究审视，重心在\"认真查\"，🤓 是厚框眼镜的呆萌书呆，重心在\"我就是宅\"；和 🤖 比，🤖 指机械化或 AI，🤓 指人的 nerd 气质，一个冰冷一个可爱。", en: "A face with large glasses and buck teeth, used to self-deprecatingly label oneself a nerd, geek, or studious type. It often accompanies sharing obscure facts, late-night deep dives, or playful banter about being tech-obsessed. Affectionate rather than insulting, it differs from the scrutinizing monocle of 🧐 in that it owns the dorkiness rather than inspecting something."},
  '🧐': {zh: "用于\"让我仔细品一品\"的考究场景。比如看到一句措辞微妙的话、一条数据存疑的结论、一个看似有坑的 offer 或合同条款时发它，表示要拿放大镜细看；对方甩过来一个经不起推敲的论断，也会先回它表示存疑。情绪强度中性偏审视，是这批表情里最\"带脑子\"的一个，比 🤨 的纯怀疑多一层考据意味，姿态更冷静。易混淆对比：和 🤨 的区别——🤨 是挑眉的本能质疑，情绪更冲、更主观，🧐 是单片眼镜的客观求证，姿态更冷静；和 🤔 比，🤔 是\"我在想\"，🧐 是\"我在查你\"，一个内省一个对外。", en: "A face wearing a monocle, as if examining something closely through a magnifying lens. It signals scrutiny, due diligence, and \"let me fact-check this claim.\" More forensic than the instinctive raised eyebrow of 🤨 and more investigative than the vague pondering of 🤔, it projects a calm, scholarly skepticism."},
  '😕': {zh: "用于\"这就有点说不通了\"的轻度困惑场景。比如朋友发了句模棱两可的话、方案里有个逻辑小漏洞但还没严重到反对、或者收到一个价格对不上的账单时发它，表示歪头不解。情绪强度温和，是困惑梯度里最轻的一档，只是\"有点纳闷\"而非强烈纠结，也还没到担忧后果的程度。易混淆对比：和 😟 的区别——😕 是对信息本身的不解（动脑），😟 是对后果的担忧（揪心），前者是\"没看懂\"后者是\"怕出事\"；和 😖 比，😖 是五官挤成一团的强烈苦恼，😕 只是微微歪头的轻度疑惑，差着好几个量级。", en: "A face with one raised eyebrow and a slight frown, expressing mild confusion or puzzlement about something unclear. It fits an ambiguous message or a small logical inconsistency that doesn't yet feel like a real problem. The lightest step on the confusion scale—gentler than the worry of 😟 and far calmer than the crumpled distress of 😖."},
  '😟': {zh: "用于\"有点担心\"的关切场景。比如朋友说身体不太舒服、项目进度落后预期、面试结果还悬着没出来、或者家里人开车冒雨赶路时发它，表示心里一直悬着。情绪强度温和偏担忧，是忧虑梯度里较轻的一档，属于\"放在心上、轻轻牵挂\"，而非焦虑到坐立不安。易混淆对比：和同类梯度对比——😟 是轻度忧虑，😨 是害怕，😱 是惊恐尖叫，逐级增强；和 🙁 比，🙁 更多是情绪上的失落不满（向后看），😟 则是对未来具体事情的牵挂（向前悬）。", en: "A face with a slightly worried frown, used when one feels concerned or mildly anxious about an outcome—someone feeling under the weather, a slipping deadline, an unanswered interview result. It sits gently on the worry scale, above mere disappointment (🙁) but well below the fear of 😨 and the panic of 😱."},
  '🙁': {zh: "用于\"有点小失落\"的低能量负面场景。比如期待的聚会临时取消、常去的小店今天没开门、被朋友临时放了鸽子、或者排队排到自己卖光了时发它，表示闷闷不乐。情绪强度温和偏中性，是这批负面脸里最克制的一个，只是淡淡的不高兴，没有愤怒也没有担忧。易混淆对比：和 😞 的区别——🙁 是泛泛的轻微不满，😞 是明确指向某件事的失望沮丧（更具体更重）；和 😟 比，🙁 是情绪低落向后看，😟 是对未来的担忧向前悬，一个是过去时一个是将来时。", en: "A face with a slight downward frown, conveying mild displeasure or quiet disappointment when something small goes wrong—a cancelled gathering, a missed favorite item, a friend who bailed. The most restrained of the negative faces, it is a faint mood dip rather than the targeted disappointment of 😞 or the forward-looking worry of 😟."},
  '😮': {zh: "用于\"啊？没想到\"的轻度惊讶场景。比如听到一条八卦、得知同事突然离职、看到价格比预期便宜不少、或者朋友宣布要结婚时发它。情绪强度温和，是惊讶梯度里最轻的一档，只是嘴巴张开的一声\"咦\"，还没到瞪大眼睛的程度，也完全不带害怕。易混淆对比：和 😲 的区别——😮 是普通张嘴惊讶，😲 加上了瞪大的双眼，冲击感明显高一级；和 😱 比，😱 是双手捂脸的尖叫式恐惧，😮 没有任何害怕成分，纯粹是\"哦？有点意外\"的中性吃惊。", en: "A face with an open mouth, the classic \"oh?\" reaction to mild surprise—a piece of gossip, a sudden resignation, a pleasantly lower price. The lightest step on the surprise ladder, it escalates to the wide-eyed shock of 😲 and is worlds away from the fearful scream of 😱, since it carries no dread at all."},
  '😲': {zh: "用于\"这也太离谱了吧\"的较强惊讶场景。比如看到一个惊人的数据、朋友宣布闪婚、考试出分远超预期、或者同事突然中了大奖时发它，表示眼睛都瞪圆了。情绪强度偏强烈，比 😮 的普通张嘴高一级，是\"震惊但理智还在线、还能继续听\"的程度。易混淆对比：和 😮 的区别——😲 比 😮 多了瞪大的双眼，冲击感明显更强；和 🤯 比，🤯 是认知被炸开的脑洞式震惊（理智断线），😲 只是情绪上的强烈意外，脑子还转得动，刷到离谱热搜时也爱先刷它再细看。", en: "A face with wide open eyes and an open mouth, expressing stronger shock—staggering statistics, a sudden shotgun wedding, a score far beyond expectations. One notch above the plain open mouth of 😮, it stops short of the mind-exploding cognitive overload of 🤯, keeping reason intact while feeling the surprise keenly."},
  '😳': {zh: "用于脸红害羞或尴尬的场景。比如被当众夸奖、说错话被纠正、收到一段过于直白的表白、或者被人翻出黑历史时发它，表示脸一下子烫了。情绪强度温和偏窘迫，是\"社死但还没真死\"的程度，主要表现为不自在的发烫。易混淆对比：和 😅 的区别——😅 是流汗苦笑、主打笑着化解尴尬，😳 是脸红发烫、主打羞涩窘迫，一个在自救一个僵在原地；和 😊 比，😊 是从容的温柔笑，😳 是不自在地红着脸，一个放松一个紧绷，被当众点名夸奖时尤其明显。", en: "A face flushed bright red, used for blushing embarrassment, shy praise, or awkward moments like saying the wrong thing in public. It conveys a warm rush of self-consciousness—distinct from 😅, which uses a sweat-drop laugh to smooth over awkwardness, and from the relaxed warmth of 😊, since 😳 is visibly tense rather than at ease."},
  '🥺': {zh: "用于撒娇恳求、卖萌求人的高频场景。比如求朋友顺路带杯奶茶、请人帮忙 review 一下代码、被宠物照片萌到\"心化了\"、或者想求对方原谅时发它。情绪强度偏夸张但软萌，是\"用力但不讨厌\"的恳求，情绪浓度很高却显得可爱，杀伤力极强。易混淆对比：和 😢 的区别——🥺 是抬头水汪汪地求你（在\"求你\"），😢 是真的流泪难过（在\"我好惨\"），一个是手段一个是状态；和含泪感动类表情比，🥺 的泪是为了恳求而挤出来的水汪汪，目的感更强。", en: "A face with big watery puppy eyes and slightly raised brows, the ultimate pleading and coquettish emoji used to beg for a favor, ask for a favor, or show that something adorable melted one's heart. Intense yet endearing, it differs from 😢's genuine sadness by channeling tears into a request rather than a lament.", pop: "撒娇神器，求人办事、求投喂、求原谅时高频使用，杀伤力极强。"},
  '😢': {zh: "用于难过、委屈、轻微感动到掉泪的场景。比如看电影被戳中泪点、养的小植物枯了、被一句暖心话感动、或者错过末班车时发它。情绪强度温和偏伤感，是哭泣梯度里较轻的一档，一滴泪代表\"有点想哭、有点委屈\"，还没到决堤。易混淆对比：和 😭 的区别——😢 是一滴泪的克制难过，😭 是五官挤皱、泪如泉涌的情绪决堤，强度差好几级；和 🥺 比，😢 的泪是真难过（自怜），🥺 的泪是为了恳求而挤出的水汪汪（求人），一个往内一个往外。", en: "A face with a single tear rolling down, used for gentle sadness, quiet grievance, or being lightly moved—a touching film, a withered plant, a warm message. It is the restrained end of the crying scale, worlds apart from the full on-breakdown flood of 😭, and unlike 🥺 its tear reflects real sorrow rather than a strategic plea."},
  '😭': {zh: "用于情绪强烈冲击的场景，早已不一定真哭。比如看到太好笑的段子、收到太惊喜的礼物、被催婚催到崩溃、或者买到断货已久的东西时，都会刷它。情绪强度夸张外放，早已\"语气词化\"，是这批表情里情绪浓度最高的之一，高兴难过感动都能套。易混淆对比：和 😢 的区别——😭 是泪如泉涌的决堤，😢 只是一滴泪的克制；和 😂 比，😂 的泪明确是笑出来的，😭 的泪可笑可哭可感动，语义更泛化，\"太绝了\"\"裂开了\"也都能用它，适用面极广。", en: "A face bawling with squeezed-shut eyes and streaming tears, now functioning as an intensifier rather than literal weeping—used for something hilarious, an overwhelming gift, or being driven to comic frustration. It has become a general exclamation mark; compare 😢's single restrained tear, and note that unlike 😂's strictly joyful tears, 😭 covers laughter, grief, and being touched all at once.", pop: "语气词化严重，\"笑到哭\"\"太感动\"\"裂开了\"都能用，不一定真的在哭。"},
  '😱': {zh: "用于被吓到或震惊到尖叫的场景。比如突然看到恐怖画面、得知一个晴天霹雳的坏消息、被朋友恶作剧整到、或者刷到一个离谱到窒息的瓜时发它。情绪强度强烈偏夸张，是恐惧梯度的顶点之一，重心在\"害怕/惊跳/汗毛竖起\"。易混淆对比：和 😨 的区别——😨 是冒汗的害怕（还有退路、还能跑），😱 是双手捂脸尖叫的失控恐惧（腿软了）；和 🤯 比，🤯 是认知式震惊（脑子炸），😱 是情绪式惊恐（肉跳），一个动脑一个心跳加速。", en: "A face screaming with hands pressed against the cheeks, evoking Edvard Munch, used for genuine fright or a jolting shock—jump-scares, devastating news, a prank gone wrong. At the top of the fear ladder, it is far more panicked than the sweating, still-coping dread of 😨, and unlike the cerebral shock of 🤯 it is a gut-level startle response."},
  '😖': {zh: "用于纠结、想不通、拧巴的场景。比如方案改了八版还被打回、一道题死活算不对、夹在两个互相矛盾的需求之间左右为难、或者怎么都下不了决定时发它。情绪强度偏强烈，是五官皱成一团的内心拉扯，属于\"解不开的结\"。易混淆对比：和 😣 的区别——😖 是纠结苦恼（重心在\"想不通、解不开\"），😣 是咬牙硬撑（重心在\"扛着痛往前走\"），一个在解题一个在硬扛；和 😫 比，😫 是累到不行的疲倦，😖 是烦到想不通的纠结，重心完全不同。", en: "A crumpled, contorted face with gritted teeth and squeezed eyes, expressing tangled frustration and being unable to work something out—the eighth revision rejected, a stubborn math problem, conflicting demands. It leans into mental knots, distinct from 😣's clenched-teeth endurance and from the sheer exhaustion of 😫."},
  '😣': {zh: "用于咬牙硬撑、强忍难受的场景。比如带病坚持加班、忍痛继续改方案、跑步咬牙冲过终点、或者牙疼还得把饭吃完时发它，表示\"再扛一下就好\"。情绪强度偏强烈，是\"隐忍的痛苦\"，比 😖 的纠结多一层韧劲，比 😤 的赌气多一层苦。易混淆对比：和 😖 的区别——😣 是咬紧牙关的坚持（在熬），😖 是拧巴的想不通（在卡）；和 😤 比，😤 是怒从鼻出的赌气带攻击性，😣 是闷头硬扛的纯隐忍，一个带刺一个纯扛，带病硬赶 deadline 时最贴切。", en: "A face with tightly closed eyes and clenched teeth, used for gritting through hardship—working while sick, forcing through another revision, pushing to the finish line. It is suppressed endurance rather than the mental tangle of 😖, and lacks the aggressive bravado that steam-from-the-nose 😤 projects."},
  '😞': {zh: "用于明确的失望、沮丧场景。比如期待已久的活动临时泡汤、努力了很久却没拿到想要的结果、被信任的人泼了冷水、或者抢票没抢到时发它。情绪强度温和偏低落，是\"一件具体的事落空\"的失望，比泛泛的不满更指向明确。易混淆对比：和 🙁 的区别——😞 是针对具体事件的失望垂头（有事因），🙁 只是泛泛的轻微不满（说不清为啥）；和 😔 比，😔 是低头沉思式的惆怅遗憾，😞 是直接的\"没达到预期\"的沮丧，一个回味遗憾一个当场落空。", en: "A face with downcast eyes and a drooping frown, used for specific disappointments—a long-awaited event falling through, effort that didn't pay off, being let down by someone trusted. More targeted than the vague discontent of 🙁, and more directly \"expected better\" than the wistful brooding of 😔."},
  '😓': {zh: "用于尴尬、窘迫、冷汗直流的场景。比如说错话当场冷场、开会被点名答不上来、发现自己搞错了一个低级错误、或者轮到自己发言突然忘词时发它。情绪强度温和偏紧张，是\"后背发凉、额头冒汗\"的小型社死。易混淆对比：和 😅 的区别——😅 是流汗但还咧嘴笑着化解（在自救），😓 是流汗且嘴角下垂、更窘迫僵住；二者同为流汗脸，一个试图用笑救场，一个直接被尴尬定在原地，手抖着打字、恨不得原地找个地缝钻进去的时候就很传神。", en: "A downcast face with a single sweat drop and a frown, expressing awkward embarrassment or nervous cold sweat—a blunder that fell flat, being caught speechless in a meeting, realizing a silly mistake. Unlike 😅's smile-through-it sweat, 😓 lets the corners of the mouth droop, showing someone frozen rather than self-rescuing."},
  '😩': {zh: "用于累到叹气、濒临崩溃边缘的场景。比如连续加班一周、方案改到想吐、周末还被工作消息轮番轰炸、或者熬了大夜第二天还要早起时发它。情绪强度偏强烈，是\"心累到想瘫、一口气叹出来\"的程度。易混淆对比：和 😫 的区别——😩 是唉声叹气的心力交瘁（偏情绪），😫 是五官皱起的疲倦烦躁（偏身体），二者常互换但 😩 更接近情绪崩溃；和 🥱 比，🥱 只是打哈欠的轻度困乏，😩 是已经快扛不住了，周五傍晚最容易刷它，叹气连发三条都不夸张。", en: "A weary face with squeezed eyes and an open, groaning mouth, used for being emotionally drained—crunch week, endless revisions, work piling onto the weekend. It reads as a heavy, heart-felt sigh; closely related to 😫 but with more of a giving-up groan than the bodily exhaustion of 😫."},
  '😫': {zh: "用于又累又烦、身体心情一起掉线的场景。比如连续熬夜好几天、被一堆琐事磨得没脾气、坐了长途车回到家、或者一整天被会议塞满时发它。情绪强度偏强烈，是身体和精神双重的耗竭。易混淆对比：和 😩 的区别——😫 更偏身体性的\"我累垮了\"（腿软），😩 更偏情绪性的\"我心累了\"（叹气）；和 🥱 比，🥱 只是打个哈欠的轻度困或无聊，😫 是已经彻底耗竭，程度重得多，差着好几个档次，连着开一整天会的人最懂这种累，回到家只想瘫着不动。", en: "A face with furrowed brows, squeezed eyes, and a wailing open mouth, expressing combined physical and mental exhaustion—all-nighters, being ground down by chores, energy and mood both offline. Heavier than the bored yawn of 🥱 and more body-centered than the emotional sigh of 😩, it signals total depletion."},
  '🥱': {zh: "用于打哈欠、犯困、或对某事提不起兴趣的场景。比如深夜还在开会、被拉进一个自己不感兴趣的话题、听到一件已经听腻了的八卦、或者单纯表示困了想睡时发它。情绪强度温和中性，是疲倦梯度里最轻的一档，只是\"打了个哈欠\"。易混淆对比：和 😴 的区别——🥱 是张嘴打哈欠（还撑着、还在听），😴 是冒 Zzz 已经睡着（彻底关机）；和 😫 比，🥱 只是轻度的困或无聊，😫 是重度耗竭，一个刚起念一个已经累垮，听长篇大论时刷它最自然。", en: "A yawning face with a stretched open mouth and a lifted hand, used for sleepiness, boredom, or polite disinterest—a late-night meeting, a tedious topic, \"I've heard enough of this.\" The lightest tiredness on the scale, far short of the knocked-out sleeping face 😴 and the total depletion of 😫."},
  '😤': {zh: "用于憋着一股劲、不服气、赌气式决心的场景。比如被人小看后暗暗立誓要证明自己、跟自己较劲、或者\"哼，我偏要做到给你看\"时发它。情绪强度偏强烈但带韧劲，是\"气鼓鼓但憋着、没真正发火\"的程度。易混淆对比：和 😠 的区别——😤 是鼻孔喷气的憋着气（还带着斗志和不服），😠 是直接皱眉的普通发火（纯不满）；和 😡 比，😡 是涨红脸的暴怒外放，😤 是不服输的较劲内收，一个炸出来一个憋回去，被人看扁后暗自发狠时常配它。", en: "A face with a furrowed brow and steam puffing from the nostrils, conveying huffing determination, stubborn defiance, or \"oh yeah? watch me.\" It is suppressed, competitive anger—unlike the outright frown of displeasure on 😠, and far from the flushed fury of 😡, it channels heat into a clenched resolve."},
  '😡': {zh: "用于非常生气、火冒三丈的强烈场景。比如被人放了鸽子、方案被无端否定、看到不可理喻的言论、或者排队被人恶意插队时发它。情绪强度强烈，是愤怒梯度里最高的一档之一，脸都涨红了、眉毛倒竖。易混淆对比：和 😠 的区别——😡 是满脸通红的暴怒（强度拉满），😠 只是皱眉的普通恼火（还压着点）；和 😤 比，😤 是憋着劲的赌气（内收），😡 是直接炸出来的怒（外放），一个忍一个爆，真踩到底线、实在忍无可忍、脸都涨红时才上它。", en: "A bright red, furiously frowning face, used for genuinely hot anger—being stood up, having work dismissed unfairly, reading an infuriating take. Near the top of the anger ladder, it outstrips the plain frown of 😠 and is far more overt than the contained, steam-from-nose determination of 😤."},
  '😠': {zh: "用于不满、恼火、但还没到爆发的场景。比如说话被人打断、被误解了意思、计划被临时打乱、或者答应好的事被爽约时发它，表示\"我有点不爽了，请注意\"。情绪强度偏中等，是愤怒梯度里较轻的一档，只是皱眉、脸还没红。易混淆对比：和 😡 的区别——😠 是眉毛下竖的不悦（还压着火），😡 是脸涨红的暴怒（已经炸了），强度差一档；和 😒 比，😒 是撇嘴的嫌弃冷淡（冷处理），😠 是明确的火气上升（热反应），一个冷一个热。", en: "A face with angled, furrowed brows and a firm frown, expressing displeasure and irritation that hasn't yet exploded—being interrupted, misunderstood, or having plans upended. Midway on the anger scale, it is cooler than the flushed rage of 😡 and hotter than the cold side-eye disdain of 😒."},
  '🤬': {zh: "用于\"骂脏话、爆粗口、被气到口吐芬芳\"的场景。比如被离谱操作气到、看到离谱言论、打游戏遇到坑队友、或者被同事甩锅时发它，用符号遮住嘴代替满屏脏话。情绪强度强烈，是愤怒的语言化表达，比 😡 更指向\"已经骂出口\"。易混淆对比：和 😡 的区别——🤬 是嘴巴被符号封印、主打\"脏话连篇、口吐芬芳\"，😡 只是脸色暴怒没出声；本批中它代表\"真的骂了\"，是愤怒链条里最冲、最口无遮拦的一档，被坑队友气到时满屏都是它。", en: "A face with a mouth covered in symbol glyphs (like #@!$%), representing swearing, cursing, or being so enraged that expletives spill out—infuriating gameplay, outrageous takes. It verbalizes anger more than the mere red-faced fury of 😡, marking the point where one has actually started cussing."},
  '😈': {zh: "用于调皮坏笑、恶作剧得逞的场景。比如偷偷整蛊朋友成功、心里在谋划一个小恶作剧、或者\"嘿嘿，我有个坏主意\"时发它；设了个小套路逗人、憋着想搞怪时也爱用。情绪强度温和偏狡黠，是\"可爱的坏\"，没有真正的恶意，只是皮一下。易混淆对比：和 👿 的区别——😈 是带角但微笑（调皮的坏、闹着玩），👿 是怒目圆睁（凶狠的坏、来真的），一个闹着玩一个真警告；和 😏 比，😏 的坏笑是得意自信，😈 多了一对小角，恶作剧属性更明显。", en: "A grinning face with small devil horns, used for playful mischief and a \"heh, I have a wicked idea\" gleam—pulling off a harmless prank, plotting a teasing surprise. Its \"evil\" is cute and mischievous, a stark contrast to the genuinely menacing glare of 👿; compare 😏's smirk, which reads more smug than horned-up-to-no-good."},
  '👿': {zh: "用于凶狠、警告、被彻底惹毛的场景。比如被人反复挑衅、对方蹬鼻子上脸、放一句狠话警告、或者\"你再这样我可不客气了\"时发它。情绪强度强烈，是恶魔表情里真正带杀气的一个，眉弓倒竖、来者不善。易混淆对比：和 😈 的区别——👿 是皱眉怒目的恶魔（来真的、带威胁），😈 是带角微笑的恶魔（闹着玩、图一乐），一冷一热；和 😡 比，👿 多了一对角的邪恶符号，比普通红脸愤怒更具暗黑威胁感，放狠话警告对方时才动用，平时轻易不发。", en: "A fierce, frowning face with devil horns, used as a warning or when genuinely pushed too far—repeated provocation, someone overstepping, a hard ultimatum. Its menace is real, unlike the playful grin of 😈; with added horns it reads more threatening and dark than the plain red fury of 😡."},
  '💀': {zh: "原义死亡、危险，网络上几乎只用于\"笑死了/尬死了/累到死\"的自嘲。比如听到一个冷到结冰的笑话、被社死现场击倒、加班加到怀疑人生、或者吃到一口黑暗料理时发它。情绪强度夸张，是\"以死来自嘲\"，并非真的涉及死亡。易混淆对比：和 💩 的区别——💀 是\"笑死/尬死\"的灵魂出窍式自嘲（调侃自己），💩 是形容某样东西烂（吐槽事物）；和 🤡 比，🤡 是\"我像小丑一样被耍\"，💀 是\"我原地去世\"，自嘲的方向和心酸度不同。", en: "A human skull, whose literal death meaning has almost vanished online; it now stands for \"I'm dead\"—laughing to death, second-hand embarrassment to death, or being worked to death. It mocks the self rather than, say, 💩, which names something crappy like bad code; and unlike 🤡, which says \"I'm the clown being played,\" 💀 says \"I have just perished.\"", pop: "\"笑死了\"（I'm dead）、\"尴尬到想死\"\"累到原地去世\"的自嘲标配。", tip: "跟长辈或正式场合沟通时慎用，容易被误以为在表达死亡、晦气。"},
  '💩': {zh: "用于吐槽烂东西、自嘲\"一坨\"的轻松场景。比如吐槽一段烂代码、一个离谱的需求、一部烂片、或者自嘲自己刚写的稿子\"跟屎一样\"时发它。情绪强度偏调侃，是带点幽默的贬低，卡通笑脸造型把攻击性大大化解。易混淆对比：和 💀 的区别——💩 指向\"某样东西很烂\"（名词性吐槽一个事物），💀 指向\"我被击倒了\"（状态性自嘲自己）；和 🤢 比，🤢 是生理性真恶心反胃，💩 是卡通式的玩笑嫌弃，一个当真一个搞笑，改稿时自嘲最常用。", en: "A stylized, grinning pile of poo, used to call out something crappy—bad code, a ridiculous requirement, a garbage movie—or to self-deprecatingly call one's own output a pile. Its cartoon look softens the insult; unlike 💀's self-directed \"I died,\" 💩 targets an object, and unlike 🤢's genuine nausea it is mock-disgust played for laughs.", pop: "程序员高频吐槽\"这代码一坨屎\"的标配，也形容烂需求、烂方案。"},
  '🤡': {zh: "用于自嘲\"小丑竟是我自己\"、觉得整件事很荒诞的场景。比如一腔热情却被人当枪使、兴冲冲表白被拒、努力半天发现方向全错、或者饭圈\"小丑竟是我\"的自嘲时发它。情绪强度偏苦涩自嘲，是带点心酸和荒诞的\"我好可笑、我被耍了\"。易混淆对比：和 💀 的区别——🤡 是\"我像个小丑一样被耍\"（带委屈、被愚弄的荒诞感），💀 是\"我笑死/尬死\"（更纯粹的崩溃）；🤡 常连发\"🤡🤡🤡\"表示被当猴耍，比 💀 多一层屈辱感，饭圈塌房自嘲时尤其爱连发三个。", en: "A clown face, online shorthand for \"I'm the clown\"—having one's enthusiasm exploited, a rejected confession, a big effort in the wrong direction. It carries bitter self-mockery and absurdity; whereas 💀 says \"I just died,\" 🤡 says \"I was the fool up on stage,\" adding a layer of being played for a sucker.", pop: "\"🤡\" = 被当猴耍、小丑竟是我自己，也形容整件事很荒诞可笑。"},
  '👻': {zh: "用于吓人一跳、突然消失、或\"出去鬼混一下\"的轻松场景。比如玩捉迷藏后突然冒出来吓人、临时消失一会儿回个消息、调侃自己\"出去鬼混/摸鱼\"、或者万圣节前后都爱刷它。情绪强度温和调皮，是卡通幽灵式的可爱吐舌，没有真恐怖成分。易混淆对比：和 👽 的区别——👻 是幽灵（强调\"消失/突然冒出来吓人\"），👽 是外星人（强调\"奇怪、异类、看不懂\"）；和 🤡 比，👻 是躲猫猫式的俏皮，🤡 是自嘲荒诞，调性完全不同。", en: "A cute cartoon ghost sticking its tongue out, used for playful spookiness, vanishing and reappearing, or lighthearted \"ghosting\" and sneaking off. Harmless and mischievous—unlike the \"weird alien\" otherness of 👽, 👻 emphasizes disappearing and popping out to startle, and lacks the bitter self-mockery of 🤡."},
  '👽': {zh: "用于形容奇怪、异类、说话像外星语的场景。比如朋友发了一段你完全看不懂的专业黑话、某人穿搭特立独行到离谱、调侃一道题\"这写的跟外星文一样\"、或者纯觉得某件事不对劲时发它。情绪强度中性偏调侃，是\"跟我不在一个频道、来自别的星球\"。易混淆对比：和 👻 的区别——👽 强调\"异类/看不懂/不像人类\"，👻 强调\"消失/吓人\"；和 🤖 比，👽 是有机的怪异（来自别的星球，带神秘感），🤖 是机械的非人感（冰冷、程序化），一个神秘一个冷硬。", en: "An alien face with a large head and big black eyes, used when something feels weird, alien, or incomprehensible—jargon you can't decode, an outlandish outfit, a problem that reads like gibberish. It signals \"not on my wavelength\"; unlike the vanish-and-startle ghost 👻, 👽 is about otherworldly strangeness, warmer than the cold machinery of 🤖."},
  '🤖': {zh: "用于形容机器人感、AI、机械化回复的场景。比如吐槽客服答非所问像机器人、自嘲代码写得毫无感情、聊到 AI 大模型或自动化脚本、或者调侃某人说话太一本正经像机器时发它。情绪强度中性，是\"非人类/机械感\"的中性指代，不带太多褒贬。易混淆对比：和 👽 的区别——🤖 是金属机械的非人感（冰冷、程序化），👽 是外星生物的怪异感（有机、神秘）；和 🤓 比，🤓 是活生生的书呆气质（可爱），🤖 是去人格化的机械/AI，一个有人味一个没人味。", en: "A metallic robot face, used to evoke automation, AI, or mechanical impersonality—a customer service reply that feels robotic, code that runs coldly, or general chatter about AI models. Neutral and dehumanizing; unlike the organic strangeness of 👽, 🤖 projects machinery, and unlike the human dorkiness of 🤓, it strips personality out entirely.", tip: "程序员聊天高频，常指自动化脚本、机器人或 AI 模型。"},
  '😺': {zh: "用于把开心、可爱情绪\"猫化\"的场景。比如晒自家猫、夸别人发的图可爱、想用更软萌的方式表达心情好、或者单纯觉得猫脸比人脸更治愈时发它。情绪强度温和偏可爱，相当于把 😀 的咧嘴笑换成猫脸，额外加了一层软萌滤镜。易混淆对比：和 😀 的区别——😺 是猫脸咧嘴笑，多了萌系可爱属性，😀 是最普通的黄脸咧嘴笑、中性无滤镜；整体来看，猫系表情（😺😸 等）都比对应的人脸多一层\"可爱滤镜\"，情绪更甜更软，晒猫时几乎必配。", en: "A grinning yellow cat face, the feline version of a happy smile used to cuten up good moods, post cat photos, or react to something adorable. It layers a soft, cute filter over a plain grin; versus the bare yellow smile of 😀, 😺 trades neutrality for kawaii charm."},
  '❤️': {zh: "全场景通用的心，用于表达爱、喜欢、感谢、\"收到/点赞/暖心\"。比如回复朋友的关心、感谢同事的帮忙、表达对家人的爱、或者给好内容点个心时发它。情绪强度中性偏暖，是最百搭、最不挑关系亲密度的心形基准。易混淆对比：和 💕 的区别——❤️ 是单颗红心、关系普适、朋友同事都能用，💕 是两颗跳动的心、更甜更亲密；本批其他颜色心都是围绕 ❤️ 这个基准做颜色语义分化，它就是心形里的\"默认款\"，发错对象也不容易翻车。", en: "The classic red heart, the most universal way to express love, affection, thanks, or simply \"received / I like this.\" It is the baseline against which all colored hearts are differentiated—far more broadly applicable than the sweeter, more intimate pair of beating hearts 💕.", tip: "全场景通用，回复\"收到/感谢/暖心\"都可以用它，职场也不突兀。"},
  '🧡': {zh: "橙心用于温暖、友情、秋日氛围的场景。比如和老朋友叙旧、给朋友发一句温暖鼓励、分享秋天的落叶或一杯热橙茶、或者想表达\"陪伴的暖意\"时配它。情绪强度温和偏暖，比红心少一点浪漫指向，多一点随性、治愈的温度。易混淆对比：和 ❤️ 的区别——🧡 弱化了爱情指向，更偏友情与长久陪伴的暖；和 💛 比，💛 更像阳光元气、轻松明亮的友情，🧡 多一层沉稳、厚重、像焦糖一样的暖，不那么跳脱，像老朋友那种不声不响的陪伴。", en: "An orange heart conveying warmth, friendship, and autumn coziness—reconnecting with an old friend, sending encouragement, or tagging a fall photo. It softens the romance of the red heart into steadier, platicular warmth; warmer and deeper than the sunny, breezy friendship of 💛."},
  '💛': {zh: "黄心用于友情、快乐、阳光元气的场景。比如给好朋友的日常打卡、晒一张阳光明媚的照片、表达\"今天心情特别好\"、或者给一段轻松的对话加点亮色时配它。情绪强度温和偏轻快，是心形里最明亮、最无压力、最元气的一个。易混淆对比：和 🧡 的区别——💛 更轻快阳光、像元气满满的轻松陪伴，🧡 更沉稳治愈；和 💚 比，💛 是纯粹的阳光友情，💚 在部分语境会自带\"吃醋/被绿\"的网络联想，语义复杂得多，不能随便替，发之前最好确认语境。", en: "A yellow heart evoking friendship, joy, and sunny optimism—daily check-ins with a best friend, a bright photo, \"feeling sunny today.\" The lightest, most pressure-free heart of the set; breezier than the steadier 🧡 and far less semantically loaded than 💚, which can carry jealousy connotations."},
  '💚': {zh: "绿心表面代表健康、自然、环保、绿色通道，但在网络语境常被玩梗。比如调侃\"我被绿了/头顶发绿\"、小小地吃个醋、支持环保或健康生活、或者绿色心情时发它。情绪强度中性，但语义有歧义，全看语境。易混淆对比：和其他颜色心的区别——💚 最大的特点是自带\"吃醋/被绿\"的网络梗义，而 ❤️🧡💛 等纯色心都没有这层联想，所以它不能随便乱发；和 💙 比，💙 指向平静忠诚，💚 指向自然与暧昧的醋意，一冷一酸，千万别随手乱发。", en: "A green heart nominally stands for health, nature, and environmental awareness, but online it frequently plays on the \"green = jealousy / being cheated on\" meme. Ambiguous by context; this jealousy layer is the key difference from other colored hearts, whereas 💙 leans into calm loyalty rather than envy."},
  '💙': {zh: "蓝心用于信任、平静、忠诚、沉稳支持的场景。比如给靠谱的朋友表达\"我信你、站你这边\"、深夜情绪需要一个安稳的陪伴、表达对蓝色系的偏爱、或者给人稳稳的支持时配它。情绪强度偏沉静克制，是心形里最冷静、最不甜腻、最像温暖港湾的一个。易混淆对比：和 💜 的区别——💙 是理性的信任与安稳，💜 是浪漫神秘的感性；和 🖤 比，💙 还有一层温度（平静的暖、让人安心的可靠感），🖤 则冷到了暗黑、潮酷或沉重哀悼的另一端。", en: "A blue heart conveying trust, calm, loyalty, and steadiness—telling a reliable friend \"I trust you,\" offering quiet emotional support, or just loving the color blue. The calmest, least sugary heart on the chart; rational comfort rather than 💜's romantic mystery, and warmer than the dark-cool 🖤."},
  '💜': {zh: "紫心用于浪漫、神秘、优雅，以及二次元饭圈文化的高频场景。比如表达一段朦胧的好感、给自己推的偶像应援打 call、喜欢紫色系美学、或者想走一点\"氛围感\"时发它。情绪强度偏柔媚梦幻，是心形里最\"氛围感\"、最带点小神秘的一个。易混淆对比：和 💙 的区别——💜 是浪漫神秘的感性（梦幻），💙 是信任冷静的理性（可靠）；和 💖 比，💜 是单色的安静梦幻氛围，💖 是带闪光的活泼喜爱，一个静谧一个闪亮，饭圈尤其偏爱它。", en: "A purple heart evoking romance, mystery, elegance, and strong fandom culture—soft crushes, idol support, purple aesthetics. The most atmospheric and dreamy heart; emotional and romantic where 💙 is coolly rational, and quieter than the sparkly, upbeat delight of 💖."},
  '🖤': {zh: "黑心在网络上常被误解，其实它并不等于\"坏心眼/黑心商家\"。它用于暗黑美学、哥特风、潮酷态度，也用于哀悼、沉重情绪，或者\"我没事但心已黑透\"的自嘲。情绪强度偏冷酷，是心形里最冷、最有态度、最\"丧\"的一个。易混淆对比：和 ❤️ 的区别——🖤 不是红色心的反面\"坏心\"，而是酷、丧、暗黑美学或哀悼；和 🤍 比，🖤 是冷感潮酷与沉重哀悼，🤍 是纯洁与留白，一黑一白正好构成镜面对照，哥特风穿搭或 emo 时刻常配它。", en: "A black heart is widely misunderstood—it does NOT mean \"black-hearted / evil.\" It stands for dark aesthetics, goth vibes, edgy coolness, mourning, or the humorous \"my soul is black\" mood. It is the coolest, most attitudinal heart; compare 🤍's purity, and read it as style or grief rather than villainy."},
  '🤍': {zh: "白心用于纯洁、干净、简约审美，也用于哀悼、缅怀、留白感的场景。比如表达一段纯粹无杂质的心意、分享极简风穿搭或家居、纪念逝去的人、或者想给话语留一点\"空\"时配它。情绪强度偏清冷、留白，是心形里最干净、最\"空\"、最安静的一个。易混淆对比：和 🖤 的区别——🤍 是纯白的纯洁与哀悼留白，🖤 是纯黑的酷与沉重，二者是镜面对照；和 🤎 比，🤍 偏空灵纯净、向上轻飘，🤎 偏大地般的温厚踏实、向下扎根，纪念时也常用。", en: "A white heart symbolizes purity, cleanliness, minimalist aesthetics, and also mourning or remembrance—a sincere pure feeling, minimalist content, honoring someone lost. The emptiest, cleanest heart; its mirror opposite is the dark-cool 🖤, and it is more ethereal than the earthy warmth of 🤎."},
  '🤎': {zh: "棕心用于大地色、温暖踏实、复古沉稳的场景。比如分享一杯咖啡或一块巧克力、表达一种接地气的安心、喜欢棕调的穿搭或家居、或者想传递\"稳稳的幸福\"时发它。情绪强度偏温厚沉稳，是心形里最\"实\"、最不花哨、最接地气的一个。易混淆对比：和 🤍 的区别——🤎 是大地般的温厚与踏实（向下、厚重），🤍 是空灵的纯洁留白（向上、轻盈）；和 🧡 比，🧡 明亮温暖偏活泼跳脱，🤎 低调内敛偏厚重焦糖感，秋冬穿搭照最爱配它。", en: "A brown heart evokes earth tones, grounded warmth, coziness, and vintage steadiness—sharing coffee or chocolate, expressing down-to-earth comfort, brown aesthetics. The most solid, unflashy heart; earthier than the airy purity of 🤍 and quieter than the bright, lively warmth of 🧡."},
  '💔': {zh: "破碎的心用于心碎、失恋、遗憾、\"裂开了\"的场景。比如被分手、期待落空、错过一个重要机会、追的偶像塌房、或者夸张地\"我的心嘎巴一下碎了\"时发它。情绪强度强烈偏伤感，是心形里唯一带负面含义的，直接把\"破碎\"画在脸上。易混淆对比：它与整颗 ❤️ 互为反义——❤️ 是圆满完整的爱，💔 是这份爱的破裂；和 😭 比，😭 是情绪决堤地大哭（一种状态），💔 是精准具象地\"心裂成两半\"（一个器官般的符号），一个宣泄一个定格。", en: "A heart cracked clean in two, used for heartbreak, lost love, regret, or the hyperbolic \"my heart just shattered\"—a breakup, a missed chance, dashed expectations. It is the only negatively charged heart, the direct inverse of the whole red heart ❤️; more concrete than the flood of tears in 😭, it visualizes the organ literally splitting.", pop: "\"裂开了\"最接近的表情，失恋、翻车、塌房都在用。"},
  '💕': {zh: "两颗心并排，表达甜蜜、心动和双向奔赴的感情。在情侣日常聊天、闺蜜分享好消息、表达「我们心连心」时常用，也适合发给暗恋对象暗示好感。情绪强度偏温和到中等，比单颗 ❤️ 多了一层「双向」「互动」的意味，但比 💖 的闪亮感更内敛。与 ❤️ 的区别在于：❤️ 是通用的爱，可以发给任何人；💕 更偏向亲密关系和双向情感，发给普通朋友可能显得过于暧昧。与 💞 的区别在于：💕 是静态并排，💞 是旋转动态，后者情绪更活泼雀跃。", en: "Two pink hearts side by side, conveying sweetness, mutual affection, and a sense of \"we are in this together.\" It is commonly used in daily chats between couples, when close friends share good news, or to hint at a crush. The emotion intensity is mild to moderate — warmer than a single ❤️ because it implies reciprocity, but more restrained than the sparkling 💖. Unlike ❤️ which is universally appropriate for anyone, 💕 leans toward intimate relationships and may feel too flirtatious for casual friends. Unlike 💞 which shows revolving hearts, 💕 is static and feels more steady and gentle."},
  '💞': {zh: "三颗心旋转环绕，表达强烈的爱意、心动和满满的幸福感。在热恋期日常聊天、纪念日祝福、看到特别喜欢的人或事物时常用，也适合表达「被爱团团包围」的感觉。情绪强度偏高，动态旋转的视觉效果让它比静态的 💕 更活泼、更有雀跃感。与 💕 的区别在于：💕 是两颗心静态并排，偏温柔稳定；💞 是三颗心旋转，偏兴奋雀跃。与 💗 的区别在于：💗 是一颗心在变大，强调「越来越爱」的过程感；💞 强调被爱意环绕的氛围和沉浸感。", en: "Three hearts revolving around each other, expressing intense love, excitement, and the feeling of being surrounded by affection. Often used during the honeymoon phase of a relationship, in anniversary wishes, or when seeing something deeply beloved. The emotion intensity is high — the rotating animation makes it more lively and effervescent than the static 💕. Unlike 💕 which shows two static hearts and feels steady, 💞 feels dynamic and jubilant. Unlike 💗 which depicts one heart growing larger (emphasizing love increasing over time), 💞 emphasizes the atmosphere of being immersed in love."},
  '💓': {zh: "一颗心在跳动，带有动感线，表达心动、紧张、心跳加速。在看到喜欢的人、紧张期待、表达「我心跳好快」时常用，也适合形容激动或小鹿乱撞的心情。情绪强度中等偏高，跳动的视觉效果直接传达「心跳」的生理感受，比静态的心更有张力。与 💗 的区别在于：💓 是心跳（搏动），强调瞬间的心动和紧张；💗 是心在变大，强调感情在增长。与 ❤️ 的区别在于：❤️ 是稳定的爱，💓 是悸动的、带有紧张感的心动，更适合描述「怦然心动」的瞬间。", en: "A beating heart with motion lines, expressing heart-pounding excitement, nervousness, and a racing pulse. Commonly used when seeing a crush, during tense anticipation, or to say \"my heart is beating so fast.\" The emotion intensity is medium-high — the pulsing visual directly conveys the physical sensation of a heartbeat, making it more visceral than a static heart. Unlike 💗 which shows a heart growing larger (emphasizing increasing affection), 💓 emphasizes a sudden, nervous flutter. Unlike ❤️ which conveys steady love, 💓 captures a fleeting, thrilling moment of palpitation."},
  '💗': {zh: "一颗心由小变大，表达越来越爱、感情持续升温、爱意不断增长。在关系升温期、表达「我越来越喜欢你了」、看到对方做了很暖心的事时常用。情绪强度中等，动态变大的效果传达「递增」的过程感，比静态 ❤️ 更有叙事性和时间感。与 💓 的区别在于：💓 是心跳搏动，强调瞬间心动；💗 是心在变大，强调感情随时间增长。与 💕 的区别在于：💕 是两颗心并排，强调双向；💗 是一颗心变化，强调单方面感情的加深，适合表达「我对你的爱与日俱增」。", en: "A heart growing from small to large, expressing deepening affection, warming feelings, and love that grows over time. Often used when a relationship is getting closer, to say \"I like you more and more,\" or when someone does something heartwarming. The emotion intensity is medium — the growing animation conveys a sense of progression and narrative, more story-like than a static ❤️. Unlike 💓 which pulses (emphasizing a sudden flutter), 💗 emphasizes affection accumulating over time. Unlike 💕 which shows two hearts (emphasizing mutuality), 💗 shows one heart changing, highlighting one-sided deepening of feelings."},
  '💖': {zh: "一颗心周围有闪光，表达闪耀的爱、开心、幸福感和被甜到。在收到惊喜、看到可爱的事物、表达「太甜了」时常用，也适合追星和应援场景。情绪强度偏高，闪光效果让它比普通的心更华丽、更有「闪闪发光」的感觉。与 ✨ 的区别在于：✨ 是纯闪光装饰，可以搭配任何内容；💖 是带闪光的心，专门表达爱意和开心。与 💗 的区别在于：💗 是心在变大，强调增长；💖 是心在闪光，强调闪耀、绚烂和幸福感，适合表达「被甜到发光」的心情。", en: "A heart surrounded by sparkles, expressing glittering love, joy, happiness, and being utterly charmed. Commonly used when receiving a surprise, seeing something adorable, or exclaiming \"this is too sweet.\" It is also popular in fan culture and support contexts. The emotion intensity is high — the sparkles make it more ornate and luminous than a plain heart. Unlike ✨ which is pure decorative sparkle that can accompany anything, 💖 is a heart with sparkles, specifically conveying affection and delight. Unlike 💗 which grows larger (emphasizing growth), 💖 sparkles, emphasizing radiance, brilliance, and overwhelming happiness."},
  '💘': {zh: "一颗心被丘比特之箭射中，表达一见钟情、坠入爱河、被爱神击中。在表白、描述「一眼心动」、情人节祝福时常用，也适合调侃「被射中了」。情绪强度高，箭的意象直接指向「爱情」和「命中注定」，是所有心形中最具浪漫指向性的。与 ❤️ 的区别在于：❤️ 是通用的爱，范围广；💘 特指 romantic love 和一见钟情。与 💝 的区别在于：💝 是礼物的心，强调心意和赠送；💘 是被射中的心，强调被动的心动和命运感，适合描述「毫无防备就爱上了」。", en: "A heart pierced by Cupid's arrow, expressing love at first sight, falling deeply in love, and being struck by romance. Often used in confessions, when describing an instant crush, or in Valentine's Day wishes. The emotion intensity is high — the arrow imagery directly points to romantic love and destiny, making it the most romantically specific of all heart emojis. Unlike ❤️ which is a universal expression of love, 💘 specifically means romantic love and being smitten. Unlike 💝 which is a gift-wrapped heart (emphasizing thoughtfulness and giving), 💘 is a heart struck by an arrow, emphasizing passive, fateful falling in love."},
  '💝': {zh: "一颗心绑着丝带，像礼物一样，表达礼物般的心意、感谢、祝福和「把我的心送给你」。在送礼物、表达感谢、情人节和生日祝福时常用，也适合回应别人的好意。情绪强度中等偏温暖，丝带的礼物意象让它比普通的心多了一层「郑重」和「心意」的感觉。与 🎁 的区别在于：🎁 是通用礼物，可以是任何物品；💝 是心型礼物，专门表达情感层面的心意。与 💘 的区别在于：💘 是被箭射中，强调一见钟情的冲动；💝 是绑丝带的心，强调精心准备的温柔心意和感恩之情。", en: "A heart tied with a ribbon like a gift, expressing a heartfelt present, gratitude, blessings, and \"giving you my heart.\" Commonly used when giving gifts, expressing thanks, or in Valentine's Day and birthday wishes. The emotion intensity is medium-warm — the ribbon gift imagery adds a layer of thoughtfulness and sincerity beyond a plain heart. Unlike 🎁 which is a generic gift box (could be anything), 💝 is a heart-shaped gift specifically conveying emotional affection. Unlike 💘 which is pierced by an arrow (emphasizing impulsive love at first sight), 💝 is a ribbon-wrapped heart emphasizing carefully prepared, gentle affection and gratitude."},
  '✨': {zh: "闪光星，用于夸赞内容精彩、好看或带有\"加成\"意味。常见场景：发朋友圈配美食/自拍时加 ✨ 表精致绝了；群里发布新版本或好消息时结尾加 ✨ 表\"亮点上线\"；评论区夸人\"这条建议太棒了✨\"。情绪强度偏装饰性，属于中性偏正面的轻量感叹，不像 💯 或 🔥 那样强烈，更像给文字撒一层糖霜。易混淆对比：与 💫（头晕旋转）区分，✨ 是静态闪光点缀而非晕眩；与 🎇（烟花）区分，✨ 是日常小修饰，🎇 才是大型庆祝场面。", en: "Sparkles add a touch of glitter or excitement to a message. Use them when complimenting a post, announcing a highlight, or simply making text feel more polished. Unlike 🔥 or 💯, the tone is light and decorative rather than intense.", pop: "发朋友圈夸\"绝了\"的标配后缀。"},
  '⭐': {zh: "五角星，最经典的评分与好评符号。使用场景：给餐厅/电影打\"⭐⭐⭐⭐⭐\"五星推荐；收藏重要文章或消息标记\"⭐\"；形容某人表现优秀\"今天你 ⭐\"；产品评测\"这款产品⭐⭐⭐⭐ 推荐购买\"。情绪强度中等，核心是功能性评分语义，本身情绪波动不大，叠加多颗星星时才表强烈推荐，单颗星偏中性标记。易混淆对比：与 🌟（发光星星）区分，⭐ 侧重评分功能（一到五星量化评价），🌟 更偏情绪化赞美\"你最闪亮\"；与 ✨ 区分，✨ 是纯装饰无评分义，⭐ 必须配合数量或语境才有评价意义。", en: "The plain star is the universal symbol for rating and favoriting. Use it for star ratings, bookmarks, or praising someone's performance. It is functionally neutral on its own and only carries strong endorsement when repeated multiple times."},
  '🌟': {zh: "发光的星星，比 ⭐ 更带情绪温度的赞美符号。使用场景：夸奖同事\"你今天的汇报 🌟\"；标记本周最佳项目为\"🌟 重点项目\"；鼓励朋友\"你就是最亮的那颗 🌟\"；新人入职欢迎\"🌟 欢迎加入团队\"。情绪强度偏赞美与鼓励，比 ⭐ 的纯评分多了一层\"你最耀眼\"的主观肯定，但比 💯 的\"满分认可\"要温和，处于\"⭐\"和\"💯\"之间。易混淆对比：与 ⭐ 区分，⭐ 是冷静的评分工具，🌟 是热情的赞美表情；与 ✨ 区分，✨ 是无对象的装饰闪光，🌟 指向明确的\"主角/亮点\"，有明确的夸赞对象。", en: "The glowing star expresses admiration and highlights someone or something as the standout. It carries more emotional warmth than the plain ⭐ and is commonly used to praise a person, a project, or a moment of excellence."},
  '💯': {zh: "一百分符号，表示完全同意、满分认可、绝了。使用场景：群里同事提了个好方案，回\"💯 就这么干\"；朋友分享观点\"说得太对了💯\"；形容颜值或作品\"这个设计满分💯\"；面试评价\"候选人表现💯通过\"。情绪强度属于强烈感叹级，比 👍 的\"赞同\"更夸张，接近\"百分之百同意、无可挑剔\"，语气比普通点赞高两档。易混淆对比：与 ✅ 区分，✅ 是\"事情做完了\"的功能性确认，💯 是\"这件事满分\"的情绪化吹捧；与 🔥 区分，🔥 强调热度和流行状态，💯 强调完美和无条件认可。", en: "The hundred symbol expresses perfect agreement or top marks. Use it to endorse an idea enthusiastically, rate something as flawless, or show total support. It is stronger than a simple thumbs-up and is often paired with slang like \"yyds.\"", pop: "yyds 的经典搭配。"},
  '🔥': {zh: "火焰，表示热门、厉害、燃、状态火热。使用场景：项目数据暴涨时说\"这周 DAU 🔥\"；形容某人状态极佳\"他最近状态🔥\"；推荐爆款内容\"这首歌真的🔥\"；代码重构后性能飙升\"优化完 🔥了\"。情绪强度强烈，传递激情和热度，比 ⭐ 的中性评价高一个量级，但比 🎉 的庆祝更偏向\"持续燃烧\"的进行态而非一次性爆发。易混淆对比：与 💯 区分，💯 是\"满分认可\"的瞬间判断，🔥 是\"持续热门\"的状态描述；与 🎉 区分，🎉 是庆祝动作，🔥 是热度本身，不必然伴随庆祝动作。", en: "Fire signals that something is hot, trending, or impressive. Use it for booming metrics, great form, or viral content. The tone is energetic and sustained rather than a one-time celebration.", pop: "\"这个项目真火\"\"状态火热\"都用它。"},
  '🎉': {zh: "拉炮彩带，通用庆祝表情，工作生活双高频。使用场景：项目上线群里刷\"🎉🎉🎉\"；同事生日发\"🎉 生日快乐\"；产品得奖或里程碑达成时发🎉表祝贺；论文过审\"🎉 终于接收了\"。情绪强度中等偏强，是庆祝类表情里最通用的一个，适用于工作和生活场景，叠加多个🎉时庆祝感升级。易混淆对比：与 🎊 区分，🎉 是单只拉炮\"啪\"一下，🎊 是满屏纸屑飞舞，后者庆祝规格更高；与 🥳 区分，🥳 是个人派对脸（自己嗨），🎉 是公共庆祝动作（一起嗨），参与感不同。", en: "The party popper is the all-purpose celebration emoji. Use it for launches, birthdays, awards, or any milestone worth cheering. It strikes a balance between personal joy and collective celebration, and stacking multiple amplifies the mood.", tip: "项目上线、生日、得奖的通用庆祝表情。"},
  '🎊': {zh: "五彩纸屑球，与 🎉 同义但庆祝感更强、规格更高。使用场景：重大版本发布、团队拿下大客户、升职加薪、公司融资等\"大场面\"时用 🎊；比 🎉 多一层\"满屏飘花\"的隆重感，通常在真正的里程碑时刻才出现。情绪强度高于 🎉，属于强烈庆祝，通常在真正的里程碑时刻才用，小事用 🎉 即可，大喜事才上 🎊。易混淆对比：与 🎉 区分，🎉 是\"啪\"一下的拉炮，🎊 是满天纸屑飞舞，后者更盛大更铺张；与 🎂 区分，🎂 是生日专属道具，🎊 不限定场合，任何重大庆祝都可使用。", en: "The confetti ball is the amplified version of 🎉. Reserve it for major milestones, big wins, and grand celebrations where you want the full confetti-blast effect rather than a single popper. It signals a bigger deal."},
  '🎂': {zh: "生日蛋糕，专用于生日场景的温馨表情。使用场景：朋友生日发\"🎂 生日快乐！又年轻了一岁\"；公司群里祝同事生日快乐\"🎂 祝XX生日快乐\"；日期提醒\"今天谁生日🎂\"；自己自嘲\"又长一岁🎂\"。情绪强度温馨中性，是生日祝福的标配道具，不用于其他庆祝场合，搭配蜡烛暗示年龄。易混淆对比：与 🎉 区分，🎉 是万能庆祝（上线、得奖、升职都能用），🎂 严格绑定生日这一个场景；与 🎁 区分，🎁 是礼物本身（做活动发福利也能用），🎂 只在蛋糕/生日语境下出现，场景更窄。", en: "The birthday cake is exclusively tied to birthdays and celebrations of another year. It is warm and specific, unlike the generic celebration symbols. Use it for birthday wishes and little else."},
  '🎁': {zh: "包装好的礼物，表礼物、惊喜、福利发放。使用场景：做活动发福利\"🎁 评论区抽三位送周边\"；朋友生日\"给你准备了 🎁 猜猜是什么\"；产品上新\"新功能惊喜 🎁 限时领取\"；节日福利\"🎁 中秋礼包已发\"。情绪强度温馨带期待，比单纯说\"有惊喜\"更具象，暗示\"打开会有好东西\"。易混淆对比：与 💝（绑丝带的心）区分，💝 是情感心意的礼物（偏恋爱告白），🎁 是实物/福利的通用礼物；与 🎂 区分，🎂 仅限生日，🎁 任何送礼/发福利场景都可用，范围更广。", en: "The wrapped gift represents presents, surprises, or perks. Use it for giveaways, benefits, or when teasing a surprise. It feels warm and anticipatory rather than romantic, and works for both personal and marketing contexts."},
  '🚀': {zh: "火箭，表示起飞、上线、冲刺、快速增长，互联网圈高频。使用场景：产品发布\"v2.0 正式上线🚀\"；数据暴涨\"这周用户量火箭般上涨🚀\"；创业/冲刺阶段\"团队起飞了🚀\"；新项目启动\"新项目🚀 冲冲冲\"。情绪强度强烈积极，自带加速度感，是互联网和创业圈最高频的表情之一，比普通加油更有爆发画面。易混淆对比：与 🎉 区分，🎉 是庆祝\"已经成了\"的结果，🚀 是\"正在起飞\"的上升过程感；与 💪 区分，💪 是持续努力坚持，🚀 是结果爆发式增长，一静一动。", en: "The rocket signals launch, rapid growth, and takeoff. It is ubiquitous in tech and startup culture for product releases and explosive metrics. The tone is dynamic and forward-moving, implying acceleration rather than steady effort.", pop: "创业圈/互联网\"起飞\"的代名词。"},
  '✅': {zh: "对勾按钮，功能性确认符号，工作流高频。使用场景：任务清单标记\"已完成 ✅\"；审批通过\"需求已确认 ✅\"；验收\"测试全部通过 ✅\"；打卡\"今日学习✅\"。情绪强度中性偏确认，不带感情色彩，就是\"这事办完了/没问题\"的状态标记，偏工具理性。易混淆对比：与 ✔️（纯对勾）区分，✅ 带按钮边框，有\"可点击确认\"的操作感和完成感，✔️ 是纯符号装饰无按钮语义；与 ❌ 区分，✅ 是通过，❌ 是否决，二者是工作流里的正反状态对，配合使用标记任务结果。", en: "The check mark button is the functional \"done\" or \"approved\" marker. Use it in task lists, sign-offs, and confirmations. It is neutral and operational, distinct from the plain ✔️ which lacks the button affordance.", tip: "任务状态\"已完成\"最常用。"},
  '❌': {zh: "叉号，表示错误、否决、失败、关闭。使用场景：方案被否\"这个思路 ❌ 不行\"；需求打回\"这里 ❌ 需要改\"；测试失败\"用例 ❌ 未通过\"；问卷选项\"以上都不对❌\"。情绪强度中性偏否定，是 ✅ 的反面，直接明确但不情绪化，就是\"这个不行\"。易混淆对比：与 🚫（禁止标志）区分，❌ 是\"错了/不行\"的判断性结论，🚫 是\"严禁\"的禁止令，后者语气更强硬带法令感；与 ⭕ 区分，⭕ 是圆圈（常表正确或零分），❌ 是叉号（表错误），二者在评分场景里完全相反。", en: "The cross mark signals error, rejection, or failure. It is the direct opposite of ✅ and is used to mark something as wrong, vetoed, or closed. It is decisive without being emotional."},
  '⏳': {zh: "正在流沙的沙漏，表示等待中、进行中、倒计时。使用场景：任务还在跑\"⏳ CI 构建中\"；等待回复\"⏳ 还在等产品确认\"；倒计时活动\"⏳ 距活动开始还有2小时\"；订单处理\"⏳ 正在支付\"。情绪强度中性提示，核心是\"还没结束，正在进行\"，带一点耐心等待的意味。易混淆对比：与 ⌛（沙漏已流完）区分，⏳ 是沙子还在漏=进行中，⌛ 是沙子漏完了=时间到/结束，这是最经典的一对反义词；与 ⏰（闹钟）区分，⏰ 是主动提醒\"该干嘛了\"，⏳ 是被动等待\"还在等别人\"。", en: "The hourglass with sand still flowing means waiting, in progress, or counting down. Use it for running builds, pending reviews, or active timers. It is the \"not done yet\" counterpart to ⌛.", tip: "工作语境 = 任务进行中/待完成。"},
  '⌛': {zh: "沙漏已流完，表示时间到、结束、截止。使用场景：活动截止\"⌛ 报名今晚截止\"；任务超时\"⌛ 时间到了没做完\"；倒计时归零\"⌛⏳⌛\"；面试时间到\"⌛ 面试结束\"。情绪强度中性，传递\"到期/终结\"信号，不焦虑但有明确截止感，提示\"再不做就晚了\"。易混淆对比：与 ⏳ 区分，⌛ 是沙漏流完=结束/到期，⏳ 是正在流沙=进行中，这一对在工作流里分别标记\"done\"和\"doing\"两个状态；与 🔚（结束箭头）区分，⌛ 强调时间维度的到期，🔚 强调流程终点。", en: "The hourglass with sand finished means time is up, deadline reached, or something has ended. It is the \"done timer\" counterpart to ⏳. Use it for deadlines, expiry notices, or countdowns that have hit zero."},
  '⏰': {zh: "闹钟，表示提醒、早起、时间紧迫。使用场景：提醒会议\"⏰ 下午3点评审别忘了\"；催进度\"⏰ 快到 deadline 了大家抓紧\"；早起打卡\"⏰ 7点起床搬砖\"；约会提醒\"⏰ 别迟到了\"。情绪强度带催促感，比 📅 的\"计划\"更紧迫，自带铃声焦虑，暗示\"再不行动就来不及了\"。易混淆对比：与 ⏳ 区分，⏰ 是主动响铃提醒\"该行动了\"，⏳ 是被动等待\"还在跑\"；与 📅 区分，📅 是日程安排（哪天做），⏰ 是时间提醒（几点了别忘），一个远期一个近期。", en: "The alarm clock signals a reminder, a wake-up call, or time pressure. It is more urgent than a calendar entry and used to nudge someone about an upcoming event or deadline. It implies urgency."},
  '📅': {zh: "日历，表示日程、日期、会议安排。使用场景：约会议\"📅 下周三下午有空吗\"；发布排期\"📅 预计周五上线\"；日程提醒\"📅 明天记得交周报\"；假期安排\"📅 国庆放假通知\"。情绪强度中性计划性，不催促，只标记\"什么时候\"，偏理性规划。易混淆对比：与 📆（挂历）区分，📅 更通用（手机日历图标感），📆 更强调\"展示某一天的具体日期\"；与 ⏰ 区分，📅 是日程规划（哪天做），⏰ 是时间提醒（几点了快动），一个是规划一个是催促。", en: "The calendar marks schedules, dates, and planning. Use it to propose meetings, set release dates, or remind someone of an upcoming commitment. It is neutral and organizational rather than urgent."},
  '📝': {zh: "备忘录/写字板，表示记录、笔记、写文档、待办。使用场景：开会\"📝 我记一下要点\"；写文档\"📝 需求文档正在写\"；待办清单\"📝 本周TODO清单\"；面试记录\"📝 面经整理中\"。情绪强度中性记录，不催促不庆祝，就是\"正在写/记着\"的动作状态，偏埋头苦干。易混淆对比：与 ✏️（铅笔）区分，📝 是\"在写字板上记录\"的完整动作，✏️ 只是工具本身无动作；与 📋（剪贴板）区分，📋 是已有清单（查看/打勾的完成态），📝 是正在记录/撰写的进行态。", en: "The memo with pen represents note-taking, documenting, or writing tasks. Use it in meetings, when drafting documents, or for to-do lists. It conveys the act of recording rather than a finished checklist."},
  '📣': {zh: "喇叭/扩音器，表示通知、公告、喊话。使用场景：群公告\"📣 下周全员大会通知所有人\"；@所有人时配📣；产品功能更新广播\"📣 新功能上线\"；招聘启事\"📣 急招后端\"。情绪强度广播式提醒，比私聊消息更正式、更广覆盖，自带\"注意了大家\"的喊话感。易混淆对比：与 📢（喇叭侧面）区分，两者几乎同义，📣 正面喇叭更常见更正式；与 🔔（铃铛）区分，📣 是主动喊话通知（发布者主动广播），🔔 是被动响铃提醒（系统通知你）。", en: "The megaphone is the announcement emoji. Use it for group notices, @everyone posts, and product broadcasts. It signals a formal wide-reaching message rather than a casual chat.", tip: "群公告、@所有人 的标配。"},
  '🆗': {zh: "OK按钮，表示没问题、同意、好的。使用场景：答应别人\"🆗 那就这么定了\"；回复确认\"收到🆗 马上处理\"；表示\"这事没问题我搞定\"；轻松答应邀约\"🆗 周末见\"。情绪强度轻松确认，比 ✅ 的正式完成感更随意，像口头说\"OK\"，偏口语化回应。易混淆对比：与 ✅ 区分，✅ 是\"任务已完成\"的正式状态标记（有方框按钮），🆗 是\"没问题/同意\"的轻松口头回应；与 👌（OK手势）区分，🆗 是文字按钮版偏工作，👌 是手势版偏生活。", en: "The OK button is a casual agreement emoji. Use it to say \"sounds good\" or \"no problem\" in a relaxed way. It is lighter than the formal ✅ completion check and more conversational."},
  '💼': {zh: "公文包，表示工作、商务、上班、职业场景。使用场景：\"💼 今天出差三天\"；\"💼 工作时间勿扰\"；谈商务\"💼 合作细节聊一下\"；求职\"💼 找工作中\"。情绪强度中性职业标识，自带\"上班/正经事\"的氛围，区分工作与生活。易混淆对比：与 🏢（办公楼）区分，💼 是\"工作这个行为/身份\"（抽象），🏢 是\"公司这个地点\"（具象建筑）；与 💻 区分，💻 是具体办公工具（电脑前干活），💼 是更泛的职业身份，不限于坐在电脑前。", en: "The briefcase represents work, business, and professional life. Use it to indicate you are on the clock, heading to a meeting, or discussing something career-related. It is a neutral occupational marker."},
  '📧': {zh: "电子邮件信封，表示邮件、邮箱、发邮件。使用场景：\"📧 详情已发你邮箱，请查收\"；邮件通知\"📧 有新邮件待处理\"；商务沟通\"📧 正式邮件会跟进\"；订阅\"📧 邮件订阅每周更新\"。情绪强度中性办公信号，是邮件工作流的标记，偏正式书面沟通。易混淆对比：与 📨（收件箱）区分，📧 是邮件本身/发送动作，📨 侧重\"收到\"的动态；与 📩（新邮件带箭头）区分，📩 是\"刚收到新邮件\"的动态提示感，📧 更静态通用，不区分收发方向。", en: "The email symbol marks mail communication. Use it when mentioning an email has been sent, needs to be sent, or when referring to email channels. It is a neutral office-workflow marker."},
  '☕': {zh: "热咖啡杯，表示咖啡、休息、提神、加班伴侣。使用场景：\"☕ 下午三点犯困来一杯续命\"；约人\"楼下喝杯 ☕ 聊聊方案\"；加班自嘲\"☕ 第三杯了还得写\"；日常问候\"早☕\"。情绪强度休闲温暖，带一点\"慢下来\"或\"撑住\"的情绪，是打工人的精神图腾之一。易混淆对比：与 🍵（茶杯）区分，☕ 是美式/咖啡文化（浓黑提神），🍵 是绿茶/中式茶杯（清苦养生），场景和文化不同；与 🫖（茶壶）区分，🫖 是器具，☕ 是喝的动作和场景。", en: "The hot beverage cup represents coffee, breaks, and staying awake. Use it for coffee dates, late-night coding sessions, or midday slumps. It carries a cozy, relatable tone for office life.", tip: "\"开个会喝杯咖啡\"、加班救星。"},
  '🏢': {zh: "办公楼，表示公司、写字楼、上班地点。使用场景：\"🏢 到公司了开始干活\"；\"🏢 我们在国贸三期办公\"；远程办公对比\"今天在家不去🏢\"；出差\"🏢 总部在上海\"。情绪强度中性场景标识，标记\"公司/办公地点\"，偏现实物理空间。易混淆对比：与 💼 区分，🏢 是\"公司这个建筑/地点\"（空间具象），💼 是\"工作这个行为\"（身份抽象）；与 🏬（商场）区分，🏢 是办公楼（办公用途），🏬 是商业零售（消费用途），功能不同。", en: "The office building represents the workplace, company, or city office. Use it when referencing going in to work, the company location, or returning to HQ. It is a neutral scene marker."},
  '📊': {zh: "柱状图，表示数据、报表、业绩统计。使用场景：\"📊 本周数据报表出炉\"；\"📊 看看Q3业绩完成率\"；数据分析群里标记讨论\"📊 这组数据怎么看\"；周报配图。情绪强度中性数据，不带涨跌情绪，就是\"看图表/有数据\"的意思，偏客观理性。易混淆对比：与 📈（上升折线图）区分，📊 是静态柱状图（多维度对比，无方向），📈 是动态上升趋势（只有涨这一个方向）；与 📉 区分，📉 是下降趋势，📊 无方向，三者构成数据可视化三件套。", en: "The bar chart represents data, reports, and analytics. Use it for dashboards, performance reviews, or data discussions. It is neutral on direction—unlike 📈 or 📉 which show trend."},
  '📈': {zh: "上升趋势图，表示增长、上涨、向好。使用场景：\"📈 本月DAU涨了20%\"；\"📈 股价又创新高了\"；项目势头好\"📈 增长曲线很健康\"；业绩提升\"📈 Q2营收超预期\"。情绪强度积极上扬，自带\"越来越好\"的正向预期，是汇报好消息时的标配。易混淆对比：与 📊 区分，📈 是折线上升趋势（强调走向和方向感），📊 是静态柱状图（强调横向对比，无方向）；与 📉 区分，📈 和 📉 是一对反义词，一个涨一个跌，方向完全相反。", en: "The increasing chart shows growth, upward trends, and positive momentum. Use it for rising metrics, good stock performance, or improving results. It is inherently optimistic and signals things are getting better."},
  '📉': {zh: "下降趋势图，表示下跌、下滑、走低。使用场景：\"📉 不对，这数据跌了\"；\"📉 用户流失率上升要警惕\"；业绩下滑\"Q2 营收 📉 环比降了\"；股价\"📉 今天又绿了\"。情绪强度消极下行，自带\"在变差\"的预警感，是汇报坏消息时的搭配表情。易混淆对比：与 📈 区分，📉 和 📈 完全相反，一个跌一个涨；与 📊 区分，📊 是无方向的静态对比，📉 是明确的下降趋势，方向感极强，常用于风险预警和坏消息汇报等正式场合。", en: "The decreasing chart shows decline, drops, and downward trends. Use it for falling metrics, slipping revenue, or worsening results. It carries a cautious, negative tone and signals things are sliding."},
  '🔍': {zh: "放大镜，表示搜索、查找、调查。使用场景：\"🔍 帮我查下这个需求在哪提的\"；\"🔍 搜索一下类似方案\"；代码审查\"🔍 这里逻辑对不对\"；排查bug\"🔍 定位问题根因\"。情绪强度中性探究，就是\"找/查/排查\"的动作，偏细致深入，自带刨根问底的意味。易混淆对比：与 🔎（向右放大镜）区分，🔍 朝左、🔎 朝右，含义几乎相同只是方向差异，国内常用 🔍；与 📱（手机搜索）区分，🔍 是搜索动作本身，📱 只是设备不涉及搜索动作本身。", en: "The magnifying glass represents search, investigation, and looking into something. Use it when asking someone to look up information, investigate an issue, or audit code. It is neutral and inquisitive."},
  '📌': {zh: "图钉，表示置顶、标记重要、固定位置。使用场景：\"📌 这条消息很重要，大家务必看\"；群里置顶公告\"📌 重要：周五发版通知\"；收藏标记\"📌 先钉住回头看\"；会议纪要\"📌 行动项已钉在群里\"。情绪强度强调重要性，比普通消息多一层\"别忽略、务必注意\"的提示感。易混淆对比：与 📎（回形针）区分，📌 是置顶/固定重点（强调重要性），📎 是附件/夹文件（提示有文件附带）；与 📍（定位针）区分，📍 是地理位置标记，📌 是信息重要性标记。", en: "The pushpin marks something as pinned, important, or highlighted. Use it to pin key messages, call attention to critical updates, or bookmark something for later. It signals \"do not miss this.\""},
  '📎': {zh: "回形针，表示附件、夹住文件。使用场景：邮件里有附件\"📎 详见附件PDF\"；\"📎 需求文档链接在下面\"；提示有文件附带\"📎 已上传设计稿\"；\"📎 还有一个视频教程附在后面\"。情绪强度中性提示，就是\"这里挂了个文件\"的功能性标记，不带感情色彩，纯工具性提示。易混淆对比：与 📌 区分，📎 是附件提示（有文件附带，内容不展开），📌 是置顶强调（内容本身重要）；与 📂（文件夹）区分，📎 是单个附件文件，📂 是整个文件夹目录，范围更大。", en: "The paperclip marks attachments. Use it to signal that a file, document, or resource is attached or linked below. It is a neutral, functional attachment indicator."},
  '💻': {zh: "笔记本电脑，表示电脑、编程、远程办公。使用场景：程序员\"💻 写代码中勿扰\"；远程办公\"💻 在家办公今天\"；\"💻 电脑快没电了找充电器\"；面试\"💻 准备技术面\"。情绪强度中性工作场景，自带\"坐在电脑前专注干活\"的画面感，偏独立深度工作。易混淆对比：与 🖥️（台式机）区分，💻 是便携笔记本（随时移动办公），🖥️ 是固定台式机/显示器；与 📱 区分，💻 是电脑端大屏生产力工具，📱 是手机端便携消费工具。", en: "The laptop represents computer work, coding, and remote office. Use it when deep in focus at your machine or mentioning you are working from a portable device. It is mobile and focused."},
  '🖥️': {zh: "台式电脑/显示器，表示电脑端、大屏办公、固定工位。使用场景：\"🖥️ 公司工位台式机配置\"；对比\"手机端和🖥️端适配情况\"；监控大屏\"🖥️ 看实时数据看板\"；游戏\"🖥️ 台式机打游戏\"。情绪强度中性，强调\"固定/桌面端/大屏\"的工作环境。易混淆对比：与 💻 区分，🖥️ 是不可移动的台式显示器（固定工位），💻 是笔记本随身办公（移动场景）；与 📺 区分，🖥️ 是办公显示器（生产力用途），📺 是电视机（娱乐用途）。", en: "The desktop computer represents a fixed workstation or monitor. Use it to distinguish desktop environments from mobile or laptop contexts. It is rooted and stationary."},
  '📱': {zh: "手机，表示手机、移动端、随时联系。使用场景：\"📱 手机上看效果如何\"；\"📱 随时打电话找我\"；移动端适配\"📱 端体验优化\"；请假\"📱 手机快没电了先下线\"。情绪强度中性，标记\"手机/移动/随时在线\"的含义，偏碎片化沟通和轻量交互。易混淆对比：与 💻 区分，📱 是手机小屏（随时随身），💻 是电脑大屏（专注办公）；与 ☎️（座机）区分，📱 是移动手机（随身号码），☎️ 是固定电话（办公室座机，不便携带）。", en: "The mobile phone represents phones, mobile context, and on-the-go access. Use it to signal something is viewed on a phone, to say call me, or for mobile-first design. It is personal and portable."},
  '📦': {zh: "包裹纸箱，表示快递、发货、打包、交付。使用场景：\"📦 你的快递到了驿站\"；发版打包\"📦 构建产物已就绪\"；产品交付\"📦 第一版交付完成\"；搬家\"📦 打包了二十箱\"。情绪强度中性物流/交付，带\"东西已打包好\"的完成感和期待感。易混淆对比：与 🚚（送货卡车）区分，📦 是包裹本身（打包好的静态状态），🚚 是运输途中的动态动作；与 📮（邮筒）区分，📦 是包裹快递（大件物流），📮 是信件邮寄（小件邮政投递）。", en: "The package represents shipping, packing, and delivery. Use it for couriers, release artifacts, or product handoffs. It signals something is boxed up and ready."},
  '🚚': {zh: "送货卡车，表示物流、发货、在途运输。使用场景：\"🚚 已发货，正在路上\"；物流追踪；\"🚚 明天下午送到\"；搬家公司\"🚚 已安排车辆\"。情绪强度中性运输动态，强调\"正在运输中\"的过程感和在路上行进的意味。易混淆对比：与 📦 区分，🚚 是运输过程（车在路上跑），📦 是包裹本身（已打包好等待发出）；与 🚛（长途货运卡车）区分，🚚 是小型配送车（快递/同城配送），🚛 是长途大货车（跨城干线运输，体积更大）。", en: "The delivery truck represents shipping, transit, and logistics. Use it to track packages, announce shipments, or say something is on its way. It conveys movement in progress."},
  '🕐': {zh: "一点钟时钟，表示时间、整点、约时间。使用场景：\"🕐 下午一点见\"；\"🕐 准时到别迟到\"；时间提醒\"🕐 一点钟有会\"；约定\"🕐 周一13:00评审\"。情绪强度中性时间标记，就是\"几点/准点\"的意思，偏守时。易混淆对比：与 ⏰ 区分，🕐 是显示时间（现在几点了/约几点），⏰ 是闹钟（响铃提醒动作）；与 🕰️（十点十分）区分，🕐 指向一点钟方向，🕰️ 指向十点十分，含义都是报时只是角度不同，无本质区别。", en: "The one-o'clock clock represents time, appointments, and punctuality. Use it to specify meeting times or signal something is on schedule. It is a neutral time marker."},
  '⚠️': {zh: "警告三角，表示注意、提醒、风险。使用场景：\"⚠️ 这个需求有坑注意看\"；发布前风险提示\"⚠️ 注意兼容性问题\"；安全提醒\"⚠️ 别点不明链接\"；文档警告\"⚠️ 此操作不可逆\"。情绪强度中等警告，比普通提示更重，但不到禁止的程度，是\"小心但可以继续\"的级别。易混淆对比：与 🛑（停止标志）区分，⚠️ 是\"小心注意\"（可继续但要留心），🛑 是\"立刻停下\"（禁止继续）；与 🚧（施工）区分，⚠️ 是风险预警（提醒可能有问题），🚧 是正在施工（正在修）。", en: "The warning triangle signals caution, risk, or heads-up. Use it to flag potential pitfalls, compatibility issues, or safety concerns. It is a moderate alert—not a full stop."},
  '🛑': {zh: "停止标志（八角停字牌），表示停止、禁止、阻塞。使用场景：\"🛑 这个分支别合，有问题\"；任务卡住\"🛑 等前端接口联调\"；紧急叫停\"🛑 先停一下需求变更了\"；事故\"🛑 线上出bug了先回滚\"。情绪强度强硬停止，比 ⚠️ 的警告更进一级，直接\"别动/停\"，带紧急感。易混淆对比：与 ⚠️ 区分，🛑 是\"立刻停止\"（行动终止），⚠️ 是\"注意风险\"（继续但小心）；与 ❌ 区分，❌ 是判断对错（这件事不行），🛑 是强制叫停动作（现在别做了）。", en: "The stop sign is a hard halt. Use it to block a merge, freeze a task, or call an emergency stop. It is stronger than a warning triangle and means \"do not proceed.\"", tip: "任务状态\"阻塞\"常用。"},
  '🚧': {zh: "施工围挡，表示施工中、建设中、进行中。使用场景：页面开发中\"🚧 此功能还在建设\"；重构项目\"🚧 模块正在改造中\"；\"先别碰，🚧 施工中\"；网站维护\"🚧 系统升级中\"。情绪强度中性进行中，带\"暂时不可用但在修\"的含义，暗示\"好了会通知\"。易混淆对比：与 ⏳ 区分，🚧 是\"正在施工改造\"（工程建设语义），⏳ 是\"等待中\"（时间等待语义）；与 🛑 区分，🚧 是\"在修所以暂不可用\"（临时性），🛑 是\"完全禁止\"（强制性）。", en: "The construction sign means under construction, work in progress, or temporarily unavailable. Use it for features being built, pages being rebuilt, or modules being refactored. It signals \"coming soon, in progress.\""},
  '🎯': {zh: "靶心，射中红心，表示目标、精准、正中要害。使用场景：\"🎯 这个需求就是我想要的\"；目标对齐\"🎯 我们的OKR就这个\"；精准命中\"🎯 一句话说到点上了\"；考核\"🎯 今年目标就是这个\"。情绪强度强调精准与命中，带\"正中靶心\"的满足感和成就感。易混淆对比：与 🥇（金牌）区分，🎯 是\"精准命中目标\"（过程中的瞄准命中），🥇 是\"最终第一名\"（结果荣誉）；与 ✅ 区分，✅ 是\"完成了\"（泛完成），🎯 是\"命中了关键点\"（精准命中核心）。", en: "The bullseye represents hitting the target, precision, and dead-center accuracy. Use it when someone nails a point, aligns with a goal, or perfectly describes what you meant. It is a sharp, satisfied affirmation."},
  '🏆': {zh: "奖杯。使用场景：团队夺冠、项目里程碑、比赛拿奖时发，例如“我们季度目标达成🏆”“决赛赢了🏆，全员加餐”，也用于祝贺别人“恭喜晋级🏆”。情绪强度：偏强的胜利庆祝，比 🥇 多一层“实体奖杯+颁奖仪式感”，比 👑 的长期王者地位更聚焦“刚刚赢下这一场”，语气喜庆但不浮夸。易混淆对比：🏆 泛指冠军奖杯，🥇 特指第一名奖牌，👑 是“顶级/王者”的身份比喻而非某场比赛名次；想强调“赢了这一仗”用🏆，想强调“排名第一”用🥇。", en: "A trophy cup symbolizing victory, championship, and recognition after a competition or major milestone. Use it in team celebrations like \"we shipped the launch 🏆\" or congratulating a winner. It carries more ceremonial, object-based prestige than a simple medal, and it celebrates a single win rather than lasting status."},
  '🥇': {zh: "金牌。使用场景：夸对方“你就是全组最稳的🥇”、自评“这次绩效我要冲🥇”，常用于排名、榜单、考试成绩、游戏段位语境；比如群里报喜“本次上线零事故🥇，团队满分”。情绪强度：表达“第一/最优”的强度极高，比 🥈🥉 直接拉开档次，但比 🏆 少了颁奖仪式感，更强调“排名第一”这个冰冷事实。易混淆对比：🥇 专指第一名奖牌，🏆 是冠军奖杯（可泛指任何级别冠军），👑 是“顶级/王者”的身份化比喻；想表“成绩第一”用🥇，想表“拿下奖杯”用🏆。", en: "The gold first-place medal, signaling number one, top quality, or the highest honor. Say \"you're the best 🥇\" or \"aiming for the top 🥇\". Unlike 🏆 it emphasizes rank over ceremony, and unlike 👑 it denotes a contest result rather than royal status. It's a strong, unambiguous \"number one\" signal."},
  '👑': {zh: "皇冠。使用场景：夸人“老板/女神👑”、自称“今晚我就是女王👑”，或形容某产品是“行业👑”、某功能“天花板👑”；也常用于追星打榜时把喜欢的人捧成👑。情绪强度：表达尊贵、顶级、王者地位，语气偏玩笑式吹捧或自我加冕，比 🏆 的“刚赢一场”更持久、更身份化，适合长期挂在自我介绍或头衔旁，语气偏夸张吹捧。易混淆对比：👑 是可长期挂着的身份/地位象征，🏆 是某次胜利的奖杯，🥇 是具体第一名；三者常叠用“🏆🥇👑”把吹捧拉满。", en: "A crown denoting royalty, top-tier status, or being the best in a category. People joke \"queen of the night 👑\" or call a favorite product \"the crown jewel\". It carries a lasting, status-flavored boast stronger than a one-off trophy 🏆, and it's playful rather than literal."},
  '💡': {zh: "灯泡。使用场景：开会 brainstorm 冒出点子时“💡我有个想法，要不试试这个方案”，或夸对方思路清晰“这个思路💡绝了”，也用于表示“突然想起来了”。情绪强度：表达灵感闪现、突然开窍，语气轻快积极，强度中等——比 🧠（持续思考）更强调“灵光一现”的瞬间感，适合开启讨论而非下结论。易混淆对比：💡 是“冒出一个点子”，🧠 是“动脑子/智商高”，✨ 是“灵光/亮点”；💡 偏建议启动，✨ 偏修饰夸赞。", en: "A lightbulb, the universal icon for an idea suddenly clicking. Use it when brainstorming—\"💡 what if we…\"—or to praise a clever solution. It emphasizes the instant of inspiration more than sustained thinking (that's 🧠), and it's lighter and more action-oriented than a generic sparkles ✨."},
  '🧠': {zh: "大脑。使用场景：夸人聪明“🧠大佬带带我”、自嘲“想破头🧠也没想通”、或提醒用脑“这个需求得🧠一下再动手”；在技术讨论里也形容“烧脑方案”“逻辑缜密”，例如“这架构太🧠了，得好好消化”。情绪强度：表达智力、思考深度，语气理性而偏重，比 💡 的“灵光一现”更强调持续动脑和专业度，带一点“烧脑”的佩服又头大感。易混淆对比：🧠 偏“智商/思考能力”，💡 偏“单个点子”，🤔 偏“琢磨/犹豫”；🧠 是名词式夸赞，🤔 是动作式犹豫。", en: "A brain symbolizing intelligence, deep thinking, or putting one's mind to work. Call a skilled colleague \"🧠 genius\" or sigh \"thinking hard 🧠\". It implies sustained brainpower rather than a single flash 💡, and it's more literal than the pondering gesture 🤔."},
  '🤝': {zh: "握手。使用场景：达成合作“合作愉快🤝，期待长期共赢”、谈成项目“就这么定了🤝”、或致谢时表示“咱们达成一致了”；商务邮件或合作群结尾常配🤝表“期待合作、一言为定”。情绪强度：表达平等、协议、达成一致，语气正式而真诚，比单纯点赞 👍 更具“双方承诺”的分量，适合商务签约、对外合作等较郑重场合，比说谢谢更显双向。易混淆对比：🤝 强调双方达成共识/签约，🙌 是单方欢呼，👏 是单方鼓掌；🤝 偏商务契约感，👋 只是打招呼。", en: "A handshake representing partnership, agreement, or a deal struck. Use it to close negotiations—\"let's work together 🤝\"—or to thank someone for alignment. It carries the weight of a mutual commitment, stronger than a one-way thumbs up 👍, and it is more formal than a wave 👋."},
  '👋': {zh: "挥手。使用场景：群里打招呼“大家早👋，今天上线”、下班告别“先走一步👋”、或退群/结束对话“先撤了👋”；离职退群、项目群收尾时也常用“就此别过👋，江湖再见”。情绪强度：表达轻松的问候与告别，语气友好随意，强度低——纯礼节性信号，不带强烈情绪，常用于开启或结束一段聊天而不打扰别人，轻松不尴尬。易混淆对比：👋 是挥手打招呼/再见，🫡 是敬礼式“收到”，🙌 是举手欢呼；👋 最轻，🫡 正式硬核，🙌 热烈。", en: "A waving hand for casual hellos, goodbyes, or entering a chat—\"morning everyone 👋\", \"heading out 👋\". Its tone is light and polite, a low-intensity courtesy with little emotion. Compare it to 🫡 (a formal salute/acknowledgment) and 🙌 (enthusiastic raised hands); the wave is by far the most casual."},
  '✌️': {zh: "胜利手势。使用场景：拍照比耶“看镜头✌️”、赢了小一局说“耶✌️”、或表示数字“二”、第二名、第二件事；拍照比✌️是亚洲用户经典pose，几乎零门槛，使用频率远高于其他手势表情。情绪强度：表达轻松胜利或卖萌，语气轻快俏皮，强度比 🏆/🥇 弱得多，是“小开心”而非“大庆祝”，自带一点俏皮和不正经。易混淆对比：✌️ 是 V 字（胜利/卖萌/数字2），🤞 是交叉手指求好运，🤟 是“我爱你”手势；✌️ 通用愉快，🤞 带祈求意味。", en: "The V-sign, used for cheerful \"yay\", posing in photos, or meaning the number two. It reads as lighthearted and playful—a small win rather than a grand celebration, far softer than 🏆. Don't confuse it with 🤞 (crossed fingers for luck) or 🤟 (I love you); the V is pure upbeat."},
  '🤞': {zh: "交叉手指。使用场景：考试/面试前“🤞保佑这次稳过”、等结果“🤞希望能成”、或转发好运时“🤞接好运”；考试周、等offer、等开奖前刷🤞是常见场景，配“接好运🤞”“保佑一把过🤞”。情绪强度：表达祈祷好运、忐忑期待，语气带一丝紧张与许愿感，比 🍀（静态幸运符）更有“正在求”的动态感，常用在结果未卜的等待期，既紧张又带点小迷信的可爱。易混淆对比：🤞 是主动求好运的手势，🍀 是幸运符号（祝愿好运），🙏 是合十感谢或祈祷；🤞 偏许愿，🙏 偏谢/拜。", en: "Crossed fingers, a Western gesture of hoping for luck—\"🤞 fingers crossed for the interview\". It carries an anxious, hopeful \"please work out\" energy more active than the static 🍀 clover. Unlike 🙏 (thanks or reverent prayer), 🤞 is specifically about wishing for a favorable outcome."},
  '👌': {zh: "OK 手势。使用场景：表示没问题“👌收到，马上办”、搞定“齐活👌”、或夸完美“这波操作👌”；回复收到、确认需求时一个👌比长段文字更干脆，同事之间尤其高频。情绪强度：表示认可/完成，语气干脆利落，程度介于 👍（泛泛赞同）和 🙌（热烈庆祝）之间——比 👍 更带“确认无误”的干练，适合快速闭环。易混淆对比：👌 是“确认/搞定”，👍 是“赞/同意”，🤙 是“打电话/666”；注意在部分南欧、拉美文化中 👌 有冒犯含义，正式跨文化场合慎用。", en: "The OK hand signal meaning all good, confirmed, or perfectly handled—\"sorted 👌\". It's a crisp confirmation, a step more decisive than a generic thumbs up 👍 but far calmer than raised hands 🙌. Cultural caution: in parts of Southern Europe and Latin America the gesture is offensive, so use it carefully cross-culturally."},
  '🤙': {zh: "打电话手势。使用场景：“有事 call 我🤙”、职场“随时联系🤙”，网络上也谐音“666”表厉害“这波🤙”；哥们儿语境里“有事🤙”就是“有事打电话”，带股热乎劲儿。情绪强度：表达随性邀约/联络，语气轻松自来熟，比 📞（正式电话图标）更口语化、更哥们儿，适合熟人之间；职场对不熟的人用会显得过于随意。易混淆对比：🤙 是“给我打电话/保持联系”的手势，📞 是电话听筒图标，👋 是挥手告别；🤙 带江湖气和亲近感，📞 偏商务工具。", en: "The \"call me\" hand gesture, used to say \"reach out anytime 🤙\"—casual, buddy-like contact. Online it also doubles as \"666\" style praise. It's far more informal than the literal phone receiver 📞 and warmer than a goodbye wave 👋, carrying a laid-back, \"we're in touch\" vibe."},
  '🫡': {zh: "敬礼脸。使用场景：职场“收到指令🫡”、遵命“保证完成🫡”、或向偶像/前辈致敬“大佬🫡”；它近年流行开来，成了“收到/遵命”的萌化替代品。情绪强度：表达恭敬地接收/服从，语气硬核又带萌感，比普通“收到”更有仪式感和执行力，比打一串“收到收到收到”更有态度，也比纯文字多一层尊敬和幽默，常用于上下级、任务群里表态度。易混淆对比：🫡 是敬礼式“遵命”，👋 是随意挥手，💂 是卫兵；🫡 偏下级对上级/任务表态，👋 纯社交问候。", en: "A saluting face, a playful yet earnest way to acknowledge orders—\"roger that 🫡\", \"on it 🫡\". It reads as dutiful and a little meme-ish, more ceremonial than a plain \"received\" and warmer than a formal guard 💂. It's how internet users say \"yes sir\" with personality.", pop: "职场“收到”的硬核表达，也说“敬礼！”。"},
  '🙌': {zh: "举起双手。使用场景：庆祝胜利“终于上线🙌”、欢呼“太棒了🙌”、或表示举手认领“这个需求我🙌”；bug终于修复、方案终于过审时发🙌比说“太好了”更有释放感，有时也用来“举手报名”。情绪强度：表达兴奋庆祝，情绪强度较高，比 👏（鼓掌）更外放、比 🎉 稍收敛——是“嗨起来”的中档偏上信号，常用于事情搞定后的宣泄。易混淆对比：🙌 是双手高举欢呼，👏 是鼓掌，💪 是加油鼓劲；🙌 偏已发生的狂喜，👏 偏礼节性赞赏。", en: "Raising both hands in celebration or excitement—\"finally shipped 🙌\", \"this is awesome 🙌\". It's a high-energy cheer, more outward than clapping 👏 but less bombastic than fireworks 🎆. Unlike 💪 (encouragement for future effort), 🙌 celebrates something already won."},
  '👏': {zh: "鼓掌。使用场景：恭喜“升职快乐👏”、欢迎新人“👏👏欢迎加入”、或夸回答精彩“👏说到点上了”；新人进群、同事分享周报、有人答疑时，👏是最安全的捧场表情。情绪强度：表达赞赏/欢迎，语气礼貌而真诚，强度中等——社交润滑剂式的夸奖，比 👍 正式、比 🙌 克制；连发👏👏👏表示特别精彩，单一个则偏礼节性，适合公开群聊捧场。易混淆对比：👏 是鼓掌（赞赏/欢迎），🙌 是举手狂喜，👍 是轻量点赞；👏 适合公开场合捧场，👍 适合私聊快回。", en: "Clapping hands to applaud, welcome, or congratulate—\"congrats on the promotion 👏\". It's polite and sincere, a mid-strength social lubricant more formal than a thumbs up 👍 but more restrained than raised hands 🙌. Use it publicly to show genuine appreciation rather than silent agreement."},
  '💪': {zh: "肱二头肌。使用场景：互相打气“加油💪，一定行”、立 flag“这周减重五斤💪”、或炫耀身材/代码量；它还常出现在健身打卡、早起打卡、学习打卡里，“今日份💪”。情绪强度：表达力量、坚持、鼓劲，语气热血积极，强度偏强——是“我撑住/你顶住”的动员信号，互相@打气时必带，比“加油”两个字更有画面感和热血感。易混淆对比：💪 是加油/力量，🔥 是火热/爆火，🏋️ 是具体健身动作；💪 通用打气，🏋️ 专指锻炼场景。", en: "A flexed bicep for encouragement, resilience, or showing strength—\"keep going 💪\", \"new week new goals 💪\". It's an energetic rallying symbol stronger than a casual cheer. Unlike the literal gym lifter 🏋️, 💪 works anywhere you mean \"stay strong\".", tip: "互相打气、立 flag 的标配。"},
  '🙏': {zh: "双手合十。使用场景：感谢“多谢🙏，帮大忙了”、拜托“帮帮忙🙏，急”、祈祷“🙏明天别出问题”；求人办事前先🙏、收到帮助后回🙏，是中文聊天里最高频的礼貌手势之一。情绪强度：表达感谢/祈求，语气诚恳，是高频万能社交词；强度随语境可强可弱，一个🙏能顶一句“谢谢/拜托了”，几乎万能。易混淆对比：⚠️文化差异——🙏 在欧美常被误读为“击掌/高五”，在中文语境是“谢谢/拜托/拜托了”；别和 💆（按摩放松）混，它是合十手势而非舒缓动作。", en: "Folded hands, used in Chinese chat to thank, plead, or pray—\"thanks a million 🙏\", \"please help 🙏\". It's a versatile, earnest sign of gratitude or request. Cultural note: in the West it's often read as a high-five, so Western readers may misinterpret it; context matters.", pop: "在欧美常被理解为“击掌/高五”，存在文化差异。", tip: "感谢回复最常用；别误读成单纯祈祷。"},
  '👍': {zh: "拇指向上。使用场景：快速确认“收到👍”、赞同“可以👍，就这么办”、或随手点赞朋友圈；不过对方发长文详细方案时只回一个👍，容易被解读为没认真看，正式回复建议配一句说明。情绪强度：表达同意/已读，语气轻量，单独发一个 👍 常被解读为“敷衍式已读”——强度偏低，正式提议时只回👍容易显冷淡。易混淆对比：👍 是轻量同意，👌 是“确认无误”，🙌 是热烈欢呼；⚠️在中东、部分南美文化中 👍 类似竖中指，有冒犯意味，跨文化慎用。", en: "A thumbs up for quick approval or read-receipt—\"got it 👍\", \"sounds good 👍\". It's lightweight; a lone 👍 can come off as a dismissive read-receipt. Cultural warning: in parts of the Middle East and South America it is offensive, so avoid it cross-culturally. Compare 👌 (confirmed) and 🙌 (celebration).", pop: "在职场被认为“敷衍式已读”也源于它——单独回复 👍 显得冷淡。"},
  '👎': {zh: "拇指向下。使用场景：吐槽“这方案不行👎”、差评“电影烂片👎”、或玩笑式反对“这个需求我👎”；它在评论区、弹幕里常用来表达“这波我不买账”。情绪强度：表达反对/差评，语气直接但多用于自嘲或调侃，比文字批评委婉、比 🤮（厌恶）温和，是一种相对轻松的“我不买账”；但和熟人互怼居多，公开场合对客户或上级使用要谨慎，容易显得态度负面。易混淆对比：👎 是泛化差评/反对，🤮 是强烈恶心，😡 是愤怒；👎 偏吐槽，🤮 偏生理厌恶。", en: "A thumbs down for disapproval, dislike, or a bad review—\"this plan doesn't work 👎\", \"total flop 👎\". It's a direct but often playful put-down, milder than the disgust of 🤮 or the anger of 😡. It's the casual counterpart to the approving 👍."},
  '🌙': {zh: "弯月。使用场景：道晚安“晚安🌙，好梦”、深夜感慨“又到这个点🌙”、或表达浪漫“月色真美🌙”；深夜聊完天道晚安“🌙晚安，做个好梦”几乎是标配，也适合发给在意的人道一声晚安、表关心。情绪强度：表达夜晚/温柔，语气静谧松弛，强度低——是安眠、情绪降温的信号，适合把氛围往安静、抒情上带；它比直接说“睡了”更温柔。易混淆对比：🌙 是弯月（夜晚/晚安），🌃 是城市星空夜景（加班），🌕 是圆月；🌙 偏温柔抒情，🌃 偏加班自嘲。", en: "A crescent moon for night, goodnight, or a dreamy mood—\"sleep well 🌙\", \"up this late again 🌙\". It's soft and low-energy, signaling wind-down. Compare 🌃 (city night, often self-mocking over overtime) and 🌕 (full moon); the crescent is the gentler, more romantic choice."},
  '🌃': {zh: "星空夜景。使用场景：加班吐槽“又是凌晨🌃，还在改”、分享夜景“城市夜真美🌃”、或失眠“睡不着🌃”；深夜还在群里冒泡、朋友圈发加班图配🌃，都是打工人的无声吐槽。情绪强度：表达深夜氛围，常带“熬夜/加班”的无奈自嘲，情绪偏疲惫但文艺，常用于深夜还在线的人之间共鸣，也能分享夜景、表“夜猫子还醒着”。易混淆对比：🌃 是城市夜景（含建筑灯光），🌙 是纯弯月，🌌 是银河；🌃 偏都市深夜，🌙 偏温柔晚安。深夜还在群里冒泡时，它就是最贴切的配图。", en: "A starry night over a city skyline, often used for late-night vibes or self-deprecating overtime—\"another night at the office 🌃\". It carries a tired but atmospheric tone. Unlike the gentle crescent 🌙, it's specifically urban night scenes, and unlike 🌌 it's not deep-space galaxy.", pop: "加班党“又是深夜”的自嘲。"},
  '⚡': {zh: "闪电。使用场景：夸速度“秒回⚡，效率拉满”、表充电/来电“手机⚡充着”、或形容爆发力“这波输出⚡，直接秒掉”；形容充电“电量⚡满格”、网速“快到⚡”、回复“秒回⚡”都通用。情绪强度：表达极速/能量，语气干脆带劲，强度中高——是“快得像闪电”的强调，画面感就是“一下到位、瞬间完成”，适合形容瞬间完成或充电满格。易混淆对比：⚡ 是闪电（快/电），🔥 是火热/火爆，🚀 是起飞/飙升；⚡ 偏瞬间速度，🔥 偏热度，🚀 偏上升势头。", en: "A lightning bolt signaling electricity, speed, or explosive energy—\"instant reply ⚡\", \"charged up ⚡\". It's a punchy emphasis on speed, stronger than a plain fast icon. Distinguish it from 🔥 (heat/trending) and 🚀 (taking off); ⚡ implies a sudden, instantaneous zap."},
  '🏠': {zh: "房子。使用场景：下班“到家了🏠，终于歇着”、租房/装修“看看🏠户型”、或表达想宅家“周末就想🏠，哪儿也不去”；结束出差说“终于🏠了”、周末计划“宅🏠”，都带着卸下压力的松弛感。情绪强度：表达家/归处，语气安稳温暖，强度低——是“回到舒适区”的放松信号，适合收尾、回家、躺平时发，也常和“回家”连用表归属感。易混淆对比：🏠 是普通住宅（家），🏡 是带花园的乡居房，🏢 是办公楼；🏠 情感归属强，🏢 偏办公场所。", en: "A house symbolizing home, going home, or settling in—\"made it home 🏠\", \"just want to stay in 🏠\". It's warm and low-key, signaling comfort and return. Compare 🏡 (a rural garden house) and 🏢 (an office building); 🏠 is the emotional \"home\" more than architecture."},
  '✈️': {zh: "飞机。使用场景：出差“明天飞深圳✈️，周一回”、旅行“假期出发✈️，目的地待定”、值机/航班动态“延误了✈️”；朋友圈旅行九宫格常以✈️开头，表“出发/在路上”。情绪强度：表达出行/在路上，语气轻快带期待，强度中等——是“动起来、人在路上”的信号，常用于行程报备、约接机、查航班。易混淆对比：✈️ 是飞行/出差旅行，🚗 是自驾，🚄 是高铁；✈️ 偏长途/远程，🚄 偏国内中短途。它一出现就说明人在路上了。", en: "An airplane for flights, business trips, or travel—\"flying to Shenzhen tomorrow ✈️\", \"off on holiday ✈️\". It's an upbeat \"on the move\" signal. Unlike 🚗 (road trip) or 🚄 (high-speed rail), ✈️ implies longer-distance or cross-border travel."},
  '🎮': {zh: "游戏手柄。使用场景：约队友“晚上开黑🎮，五缺一”、自嘲摸鱼“摸会儿鱼🎮，马上回来”、讨论游戏“新赛季🎮冲分”；“开黑🎮”“上号🎮”是约队友黑话。情绪强度：表达打游戏/电竞，语气轻松娱乐，强度低——纯休闲标签，常用于约局或报备在玩，也用来表“我在玩游戏，稍后回”，自带一点摸鱼的俏皮。易混淆对比：🎮 是游戏手柄（电子游戏），🕹️ 是街机摇杆，👾 是像素外星小怪；🎮 通用游戏，👾 偏复古/二次元。约队友、报在玩都靠它。", en: "A game controller for gaming, squad up, or sneaking in a play session—\"let's queue up 🎮\", \"quick break to game 🎮\". It's a light, recreational tag. Compare 🕹️ (arcade joystick) and 👾 (pixel alien, retro/otaku flavor); 🎮 is the generic \"I'm gaming\" marker."},
  '🎵': {zh: "音符。使用场景：分享歌“这首单曲循环🎵，太上头”、表达开心“走路都在哼🎵”、或形容氛围“BGM🎵起”；分享歌单、推荐BGM、心情不错哼小曲时都爱带🎵。情绪强度：表达音乐/愉悦，语气轻快，强度低——是“有旋律、心情不错”的点缀，适合烘托轻松氛围，带着轻快、文艺、小陶醉。易混淆对比：🎵 是单个八分音符（音乐），🎶 是多个音符（更热闹/合唱），🎧 是戴耳机；🎵 轻，🎶 丰富，🎧 指收听设备。分享歌单时它几乎必带。", en: "A single musical note for music, humming, or sharing a song—\"this is on repeat 🎵\", \"in the mood 🎵\". It's a light, breezy marker of melody. Unlike 🎶 (multiple notes, richer/choir feel) or 🎧 (actually wearing headphones), 🎵 is the casual \"musical vibes\" tag."},
  '🍀': {zh: "四叶草。使用场景：考试/面试前“🍀求过，保佑一把”、送祝福“明天面试好运🍀”、或抽奖时“🍀蹭个手气”；转评“接好运🍀”“还愿🍀”是抽奖、考试季常见操作。情绪强度：表达好运，语气温柔祝愿，强度低——是静态祈福符，比 🤞 的“主动求”更佛系、更像送出祝福；它比🤞少一点紧张、多一点祝福和佛系。易混淆对比：🍀 是四叶草（祝愿好运），🤞 是交叉手指（主动求好运），🌻 是向日葵（阳光积极）；🍀 偏祝福他人，🤞 偏自己求。", en: "A four-leaf clover for wishing luck—\"good luck on the exam 🍀\", \"fingers crossed 🍀\". It's a gentle, passive good-charm, calmer than the active plea of 🤞. Unlike 🌻 (cheerful sunflower energy), 🍀 is specifically about fortune and blessings."},
  '🫨': {zh: "摇晃脸（Unicode 16.0 新增）。使用场景：看到离谱内容“笑到颤抖🫨，停不下来”、震惊“这操作我🫨，直接看傻”、或狂笑不止“笑到打鸣🫨”；适合“笑到岔气”“离谱到说不出话”的场景。情绪强度：表达震惊/笑到发抖，情绪张力比 😂 更夸张、比 😱 更“生理性抖动”，是新晋“笑疯了”升级款，比文字“笑死”更有冲击力。易混淆对比：🫨 是震动手抖（笑/震惊），😂 是笑出泪，😱 是单纯惊恐；🫨 夸张度更高、更新潮，适合形容“离谱到身体都在抖”。", en: "The shaking face (Unicode 16.0), vibrating with shock or uncontrollable laughter—\"I'm shaking, this is ridiculous 🫨\". It's a newer, more over-the-top laugh-shock than 😂 and more \"physical tremble\" than plain 😱. Best read as \"this broke me\".", pop: "新晋“笑死”系表情，比 😂 更夸张。"},
  '🧌': {zh: "巨魔（Unicode 16.0 新增）。使用场景：网络语境骂/自嘲“杠精本精🧌”、引战警告“别理那只🧌”、或吐槽抬杠“这人就是个🧌，见谁咬谁”；用它自嘲“我今天就是个🧌，见谁怼谁”也带点黑色幽默。情绪强度：原义北欧神话山怪，网络引申为“喷子/巨魔”，语气戏谑带嘲讽，强度中高——指向恶意挑事者，自带亚文化梗味。易混淆对比：🧌 指网络巨魔/抬杠者，👹 是日本鬼/恶鬼，🤡 是小丑（出糗）；🧌 偏恶意引战，🤡 偏自己被当小丑。", en: "A troll (Unicode 16.0), originally a Nordic myth creature, now internet slang for a provoking troll—\"ignore that 🧌\", \"resident troll 🧌\". It carries mocking, derisive energy. Unlike 👹 (demon ogre) or 🤡 (making a clown of oneself), 🧌 specifically targets someone who baits and quarrels online."},
  '🪯': {zh: "卡达/锡克教符号（Unicode 16.0 新增）。使用场景：宗教文化表达、锡克教社群身份标识，日常闲聊极少使用，只在相关话题或节庆中郑重提及，不宜出现在闲聊表情包里。情绪强度：作为严肃宗教符号，无情绪强度一说，使用须庄重，不可当玩笑调侃，也不能拿来卖萌或玩梗，日常极少使用、使用须克制。易混淆对比：🪯 是锡克教 Khanda 符号，☪️ 是伊斯兰教星月，✝️ 是基督教十字架，🕉️ 是印度教 Om；跨宗教符号不可混用乱贴。", en: "The Khanda (Unicode 16.0), the main symbol of Sikhism. It is a serious religious and cultural marker, rarely used in casual chat, and should be treated with respect—never as a joke or a meme. Do not conflate it with ☪️, ✝️, or 🕉️, which represent other faiths."},
  '🐶': {zh: "狗脸。使用场景：晒自家狗“我家修勾🐶，今天又拆家”、卖萌求原谅“🐶别生气嘛，我错了”、或自称“汪”；“修勾🐶”“汪星人🐶”是养宠人常用自称。情绪强度：表达可爱/忠诚，语气亲昵讨喜，强度低——是“软萌”信号，适合撒娇、认错、晒宠物；它也用来卖萌求放过、求原谅，比🐱更忠犬。易混淆对比：🐶 是狗脸（可爱/忠诚），🐕 是正面站立的狗（更写实），🦮 是导盲犬；🐶 偏卖萌和情绪表达，🐕 偏中性写实的狗。晒宠、撒娇都用它。", en: "A dog face for pets, cuteness, or pleading puppy eyes—\"my good boy 🐶\", \"forgive me 🐶\". It's endearing and loyal, a low-intensity charm. Unlike the realistic standing dog 🐕 or service dog 🦮, the face 🐶 is the cute, expressive choice."},
  '🐱': {zh: "猫脸。使用场景：晒猫“我家主子🐱，又掉毛”、傲娇表达“哼🐱，才不理你”、或自称猫系“本喵🐱路过”；“喵星人🐱”“我家主子🐱”是猫奴口头禅。情绪强度：表达可爱/傲娇，语气俏皮，强度低——偏高冷萌，自带一点“我懒得理你但其实很可爱”的傲娇感，和🐶的忠犬形成反差。易混淆对比：🐱 是猫脸（傲娇萌），🐈 是坐姿猫（写实），😼 是得意笑的猫；🐱 通用可爱，😼 带坏笑情绪。猫奴日常打卡高频使用，自带傲娇小滤镜。", en: "A cat face for cats, cuteness, or a coy attitude—\"my queen 🐱\", \"hmph 🐱\". It's playful and slightly aloof. Compare 🐈 (a realistic sitting cat) and 😼 (a smug cat smirk); 🐱 is the generic cute tag while 😼 already carries attitude."},
  '🐷': {zh: "猪脸。使用场景：自嘲能吃“干饭🐷，又干三碗”、骂/亲昵叫“猪头🐷，又忘了”、或形容憨厚可爱；“干饭人🐷”“猪队友🐷”都是亲昵用法，通常不带恶意。情绪强度：表达憨萌/自嘲，语气亲昵，强度低——多为善意调侃，常用于自嘲吃货或撒娇式吐槽对象，也来自嘲吃得多、睡得香，憨态可掬。易混淆对比：🐷 是猪脸（憨萌/自嘲吃），🐖 是站立猪（中性），🐽 是猪鼻子；🐷 偏卖萌自嘲，🐖 偏写实牲畜。干饭人最爱用它，憨态可掬。", en: "A pig face for cuteness, chubby jokes, or self-deprecating eating—\"pigging out 🐷\", \"you silly pig 🐷\" (affectionate). It's endearing and playful. Unlike the neutral standing pig 🐖 or the pig nose 🐽, 🐷 leans into cute, self-mocking chubbiness."},
  '🐼': {zh: "熊猫。使用场景：夸萌“太可爱了🐼，心都化了”、提到成都/熊猫基地“周末去看🐼”、或代表“国宝”“软萌担当”；熊猫脸几乎无攻击性、谁看都喜欢。情绪强度：表达软萌/珍稀，语气治愈，强度低——是“萌系顶流”，自带无害、治愈、讨喜的滤镜，是“软萌、治愈、国宝级可爱”的万能百搭表情。易混淆对比：🐼 是熊猫（萌/国宝），🐨 是考拉（也软萌），🦥 是树懒（慢萌）；🐼 带中国国宝联想，🐨 带澳洲联想。夸萌时几乎零差评。", en: "A panda for cuteness, \"national treasure\" vibes, or Chengdu references—\"so adorable 🐼\", \"going to see the pandas 🐼\". It's healing and endearing. Distinguish it from the koala 🐨 (Australian cuddly) and sloth 🦥 (slow); 🐼 carries the extra \"treasured Chinese icon\" association."},
  '🐸': {zh: "青蛙。使用场景：玩梗“青蛙王子🐸，该登场了”、表情“呱呱🐸，收到”、或青蛙头像文化“蛙蛙🐸集合”；“蛙蛙🐸”“孤寡青蛙🐸”是网络热梗，常用来自嘲单身或吃瓜。情绪强度：表达呆萌/玩梗，语气轻松，强度低——自带网络亚文化色彩，常用于搞笑、自嘲、佛系吃瓜，气质呆萌、佛系、与世无争。易混淆对比：🐸 是青蛙脸（呆萌/玩梗），🐊 是鳄鱼，🦎 是蜥蜴；🐸 常关联“青蛙表情包/梗”，🐊 偏凶猛爬行动物。吃瓜自嘲时常用。", en: "A frog face for cuteness, the \"frog prince\", or meme culture—\"ribbit 🐸\", \"frog avatar 🐸\". It's light and quirky with internet subcultural flair. Don't confuse it with the crocodile 🐊 or lizard 🦎; 🐸 leans into the soft, meme-y frog aesthetic."},
  '🦄': {zh: "独角兽。使用场景：夸稀有/梦幻“你就是我遇到的🦄，万里挑一”、形容难遇的人和事“这种机会简直🦄”、或少女心“今天也是🦄的一天”；形容难得的人才、完美的机会、稀缺产品时都爱用🦄。情绪强度：表达梦幻/稀有/独特，语气浪漫拔高，强度中高——是“万里挑一”的赞美，常用来形容难得一见，比“稀有”多了一层梦幻和理想化色彩。易混淆对比：🦄 是独角兽（梦幻稀有），🐴 是普通马，🐉 是龙；🦄 偏理想化稀有，🐴 偏现实普通。", en: "A unicorn for rarity, magic, or one-of-a-kind people—\"you're a unicorn 🦄\", \"dreamy vibes 🦄\". It's an elevated, romantic compliment, fairly strong. Unlike the ordinary horse 🐴 or dragon 🐉, 🦄 specifically means magical, almost impossibly special."},
  '🍕': {zh: "披萨。使用场景：午餐点外卖“中午披萨🍕，谁要一起”、加班加餐“点个🍕垫垫”、朋友小聚“周五披萨之夜🍕”；加班、团建、看球、生日局都离不开🍕，因为方便分食。情绪强度：表达快餐/聚餐，语气轻松随意，强度低——是“随便吃点、边吃边聊”的松弛信号，自带分享属性，没有就餐压力，是“随便聚聚”的首选。易混淆对比：🍕 是三角披萨片，🍔 是汉堡，🌭 是热狗；🍕 适合分享/多人，🍔 偏单人快餐。聚餐定外卖，它永远是首选之一。", en: "A pizza slice for lunch, takeout, or casual gatherings—\"pizza for lunch 🍕\", \"ordering in 🍕\". It's relaxed and informal. Unlike the single-serve burger 🍔, pizza 🍕 implies sharing and a laid-back group vibe."},
  '🍔': {zh: "汉堡。使用场景：快餐“来个皇堡🍔，加芝士”、吐槽垃圾食品“又吃🍔，罪恶感拉满”、或美式餐“美式三件套🍔🍟🥤”；它代表的是快餐文化和“对付一口”。情绪强度：表达快餐/饱腹，语气随意接地气，强度低——是“对付一口、快速解决”的日常信号；配🍟🥤就是标准套餐，和精致的🥂、🍰相比，🍔明显更随性、更接地气。易混淆对比：🍔 是汉堡，🍟 是薯条（常搭配），🌭 是热狗；🍔 是主餐，🍟 是小食，🍔+🍟+🥤 是经典三件套。", en: "A hamburger for fast food, a quick bite, or American-style meals—\"grab a burger 🍔\", \"guilty pleasure 🍔\". It's casual and filling. Usually paired with 🍟 fries rather than the hot dog 🌭; 🍔 reads as a standalone fast-food main."},
  '🍜': {zh: "热汤面。使用场景：“嗦碗面🍜，舒坦”、深夜放毒“深夜食堂🍜，看饿了”、或午饭打卡“今天中午🍜”；天冷、加班、想家、emo 的时候来一碗热汤面最治愈。情绪强度：表达热气腾腾的满足感，语气治愈暖胃，强度低——带烟火气，适合天冷、熬夜、想家时发；“嗦面🍜”自带声音和热气，画面感很强。易混淆对比：🍜 是带汤面（亚洲汤面/拉面），🍝 是意面，🍚 是米饭；🍜 偏汤面暖胃，🍝 偏西式拌面。天冷emo时一碗最治愈。", en: "A steaming bowl of noodles for ramen, late-night eats, or cozy meals—\"slurping noodles 🍜\", \"midnight food diary 🍜\". It's warm and comforting, full of street-food warmth. Unlike the Western pasta 🍝 or plain rice 🍚, 🍜 specifically means steaming Asian noodle soup."},
  '🍚': {zh: "米饭。使用场景：“干饭🍚，冲”、晒便当/家常菜“今晚家常菜🍚”、或到饭点“该🍚了”；它是“干饭人🍚”的核心图标，也用来报饭点、晒便当。情绪强度：表达正餐/主食，语气朴实日常，强度低——是“吃饭”的中性标签，自带家常烟火气；相比西餐表情，🍚对中文用户更有家常、饱腹、到饭点的亲切感。易混淆对比：🍚 是白米饭（亚洲主食），🍛 是咖喱饭，🍙 是饭团；🍚 偏家常正餐，🍙 偏便携小食。一到饭点就忍不住想起它。", en: "A bowl of cooked rice for a meal, a bento, or \"time to eat\"—\"chow down 🍚\", \"home cooking 🍚\". It's plain and everyday, a neutral \"meal\" marker. Unlike curry rice 🍛 or onigiri 🍙, 🍚 is the staple white rice of an ordinary home-cooked Asian meal."},
  '🍺': {zh: "啤酒杯。使用场景：下班放松“来杯🍺，解解压”、周末小酌“整两口🍺，看个球”、夜宵“🍺配烧烤，绝了”；它是“下班第一杯🍺”的标志。情绪强度：表达独饮/放松，语气随性接地气，强度低——是“下班了、松口气”的松弛信号，偏一个人或两人小酌；和🍻的热闹碰杯不同，🍺常常是一个人或两个人的安静小酌。易混淆对比：🍺 是单杯啤酒（随意独饮），🍻 是两杯相碰（干杯社交），🥂 是高脚杯碰杯（正式庆祝）；正式度：🍺 < 🍻 < 🥂。", en: "A single beer mug for after-work unwinding or a casual drink—\"one after work 🍺\", \"weekend 🍺\". It's laid-back and informal. Rising formality order: 🍺 (solo casual) → 🍻 (clinking beers, bro-ish) → 🥂 (toasting glasses, formal)."},
  '🍻': {zh: "碰杯啤酒。使用场景：聚会“走一个🍻，别养鱼”、庆祝入职/毕业“敬新生活🍻”、哥俩好“老规矩🍻”；它一出现就是“聚会、干杯、人多热闹”的信号。情绪强度：表达多人干杯/热闹，语气豪爽，强度中——比独饮 🍺 更社交、更接地气，适合兄弟局、同事小聚；配“走一个”“干了”就是典型兄弟局，比单杯🍺更外向。易混淆对比：🍻 是两杯啤酒碰杯（哥们儿式干杯），🍺 是单杯自饮，🥂 是高脚杯碰杯（更优雅正式）；🍻 偏市井热闹，🥂 偏仪式感。", en: "Two clinking beer mugs for group toasts—\"cheers 🍻\", \"celebrate with the crew 🍻\". It's hearty and social, more outgoing than the solo mug 🍺. Where 🍻 is rowdy, buddy-style beer, 🥂 is the elegant champagne-flute toast at formal events."},
  '🥂': {zh: "高脚杯碰杯。使用场景：婚礼/年会“举杯🥂，百年好合”、升职庆祝“敬未来🥂”、节日祝福“新年快乐🥂”；婚礼、年会、庆典、生日大餐才上🥂。情绪强度：表达正式/优雅的庆祝，语气体面，强度中高——比啤酒碰杯 🍻 精致，自带香槟和排面，适合需要仪式感的场合；和🍻的市井气一比，正式度立刻拉开。易混淆对比：🥂 是香槟杯碰杯（正式庆典），🍻 是啤酒杯碰杯（市井聚会），🍷 是单杯红酒；🥂 正式，🍻 随意，🍷 偏品酒。", en: "Clinking champagne flutes for formal toasts—\"to the newlyweds 🥂\", \"cheers to promotion 🥂\". It's elegant and elevated, more polished than the rowdy beer clink 🍻. Use 🥂 at weddings, galas, and milestones; save 🍻 for casual bro-outs."},
  '🍰': {zh: "短蛋糕。使用场景：下午茶“来块🍰，配咖啡”、生日祝福“生日快乐🍰，愿望成真”、或甜点诱惑“又路过蛋糕店🍰，没忍住”；下午茶、生日、犒劳自己时发🍰。情绪强度：表达甜点/甜蜜，语气甜美治愈，强度低——是“小确幸、对自己好一点”的信号；它比🎂轻巧，比🧁日常，是“小甜点、小确幸”的代表。易混淆对比：🍰 是切块蛋糕（甜点/生日），🎂 是整只生日蛋糕（插蜡烛），🧁 是纸杯蛋糕；🍰 偏日常下午茶，🎂 偏生日仪式。", en: "A slice of shortcake for afternoon tea, dessert, or birthdays—\"treat yourself 🍰\", \"happy birthday 🍰\". It's sweet and comforting. Unlike the whole candlelit birthday cake 🎂 or cupcake 🧁, 🍰 is the casual dessert/afternoon-tea slice."},
  '🌈': {zh: "彩虹。使用场景：表达希望“风雨过后🌈，总会晴”、夸赞多彩“这配色🌈，绝了”、或 LGBTQ+ 骄傲“爱就是爱🌈”；鼓励低谷中的人“会有🌈的”、夸配色缤纷都适用。情绪强度：表达希望/多元/美好，语气明亮正向，强度中——兼具浪漫与社会意涵，适合低谷打气或支持多元；它同时是希望和多元的双重符号。易混淆对比：🌈 是彩虹（希望/骄傲旗），🎨 是调色盘（创作），✨ 是闪光；🌈 带双关含义，🎨 纯指艺术。低谷打气也常用它。", en: "A rainbow for hope, colorfulness, or LGBTQ+ pride—\"after the rain 🌈\", \"love is love 🌈\". It's bright and positive, carrying both optimism and a proud community meaning. Unlike the paint palette 🎨 (art) or sparkles ✨, 🌈 is also a symbol of diversity and pride."},
  '❄️': {zh: "雪花。使用场景：天冷“冻成狗❄️，出门靠勇气”、下雪“初雪❄️，该配炸鸡了”、或形容高冷/冷淡“这态度❄️，真冷”；降温、下雪、冬至、入冬打卡时发❄️。情绪强度：表达寒冷/冬意，语气清冷，强度低——是“降温、高冷、冬天”的信号，也可暗讽对方冷淡，比如“他这态度比❄️还冷”。易混淆对比：❄️ 是雪花（冷/冬），⛄ 是雪人，🌨️ 是下雪；❄️ 偏冷感，⛄ 偏童趣雪人。入冬降温打卡时它必发，清冷感十足。", en: "A snowflake for cold, snow, or winter—\"freezing out ❄️\", \"first snow ❄️\". It's crisp and chilly, a low-intensity winter marker. Unlike the cheerful snowman ⛄ or actual snowfall 🌨️, ❄️ leans into the cold, crisp feeling itself."},
  '🎈': {zh: "气球。使用场景：生日“生日快乐🎈，又长大一岁”、派对庆祝“周五派对🎈”、或表达轻快“今天心情🎈，飘起来了”；生日祝福、开 party、心情放飞时发🎈。情绪强度：表达庆祝/童趣，语气欢快，强度低——是“小确喜”，比礼花 🎉 轻、比蛋糕 🍰 更有派对感；它像一个人偷偷开心，适合小惊喜和小庆祝。易混淆对比：🎈 是气球（派对/生日），🎉 是拉花礼炮（更盛大），🎊 是彩带；🎈 轻松日常，🎉 更隆重。小惊喜小庆祝最配它。", en: "A balloon for birthdays, parties, or lighthearted joy—\"happy birthday 🎈\", \"party time 🎈\". It's cheerful and childlike, a gentle celebration. Compare the bigger confetti popper 🎉 and streamer 🎊; 🎈 is the smaller, everyday birthday/party balloon."},
  '🎆': {zh: "烟花。使用场景：跨年“新年🎆，倒计时结束”、盛大庆祝“项目上线成功🎆”、节日氛围“今夜的江边🎆真好看”；跨年、毕业、重大节点、里程碑达成时发🎆。情绪强度：表达盛大/壮观的庆祝，情绪强度高——是“高光时刻、值得铭记”级信号，适合大节点和里程碑，像把高光时刻放大成一场烟花秀。易混淆对比：🎆 是夜空中烟花（远景盛大），🎇 是手持烟花/仙女棒（近景），🧨 是鞭炮（中国年/热闹）；🎆 宏大，🎇 小巧，🧨 喜庆年味。", en: "Fireworks in the night sky for New Year, milestones, or grand celebrations—\"happy new year 🎆\", \"big moment 🎆\". It's high-energy and spectacular. Compare the handheld sparkler 🎇 (small, close-up) and the firecracker 🧨 (festive, Chinese New Year); 🎆 is the big, sky-wide show."},
  '🧨': {zh: "鞭炮。使用场景：过年“🧨新年快乐，恭喜发财”、开业/喜庆“新店开张🧨，生意兴隆”、热闹气氛“今天小区🧨响个不停”；春节、开业、搬新家、图个吉利时发🧨。情绪强度：表达喜庆/红火，语气热闹吉利，强度中高——是“年味、开张大吉、红火热闹”的信号，节日感很强，红通通闹哄哄、年味十足。易混淆对比：🧨 是鞭炮（中国年/喜庆），🎆 是烟花（夜空盛大），🎇 是仙女棒；🧨 偏中式红火热闹，🎆 偏跨年/通用盛大。过年开工图吉利必发。", en: "A firecracker for Chinese New Year, openings, or festive bustle—\"happy new year 🧨\", \"grand opening 🧨\". It's lively and auspicious, strongly associated with Chinese-style celebration. Unlike the sky fireworks 🎆 (universal grandeur) or sparkler 🎇, 🧨 reads as red-hot, festive, and \"happy occasion\"."},
};
